#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAX_LINE 1024
#define MAX_TYPES 100
#define MAX_FUNCS 100
#define MAX_FIELDS 50
#define MAX_VALUES 100
#define MAX_EXAMPLES 100

typedef struct {
    char *name;
    char *path;
    char **fields;
    int field_count;
    char ***values;
    int value_count;
} MrshType;

typedef struct {
    char *name;
    char **inputs;
    int input_count;
    char *output;
    char *description;
    char **examples;
    int example_count;
} MrshFunction;

typedef struct {
    char *filename;
    char *content;
    MrshType types[MAX_TYPES];
    int type_count;
    MrshFunction functions[MAX_FUNCS];
    int func_count;
} MrshParser;

void init_parser(MrshParser *parser, char *filename) {
    parser->filename = strdup(filename);
    parser->content = NULL;
    parser->type_count = 0;
    parser->func_count = 0;
}

void free_parser(MrshParser *parser) {
    free(parser->filename);
    if (parser->content) free(parser->content);
    // Free types and functions memory (omitted for brevity; add free for each alloc)
}

