// ===== task-044 .AT3 [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint16_t audio_format;
    uint16_t channels;
    uint32_t sample_rate;
    uint32_t byte_rate;
    uint16_t block_align;
    uint16_t bits_per_sample;
    uint16_t extra_size;
    uint8_t *extra_params;
    uint32_t num_samples;
    uint32_t data_size;
    uint8_t *data;
    uint8_t *header_data;
    size_t header_size;
} AT3File;

AT3File* at3_create(const char* filename) {
    AT3File* at3 = malloc(sizeof(AT3File));
    memset(at3, 0, sizeof(AT3File));
    // Initialization if needed
    return at3;
}

void at3_read(AT3File* at3, const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        perror("Failed to open file");
        exit(1);
    }
    fseek(fp, 0, SEEK_END);
    size_t file_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    uint8_t* buffer = malloc(file_size);
    fread(buffer, 1, file_size, fp);
    fclose(fp);

    size_t offset = 0;

    // RIFF header
    if (memcmp(buffer + offset, "RIFF", 4) != 0) {
        fprintf(stderr, "Invalid RIFF header\n");
        exit(1);
    }
    offset += 4;
    uint32_t riff_size = *(uint32_t*)(buffer + offset) + 8;
    offset += 4;
    if (memcmp(buffer + offset, "WAVE", 4) != 0) {
        fprintf(stderr, "Invalid WAVE format\n");
        exit(1);
    }
    offset += 4;

    // fmt chunk
    if (memcmp(buffer + offset, "fmt ", 4) != 0) {
        fprintf(stderr, "Invalid fmt chunk\n");
        exit(1);
    }
    offset += 4;
    uint32_t fmt_size = *(uint32_t*)(buffer + offset);
    offset += 4;
    at3->audio_format = *(uint16_t*)(buffer + offset);
    if (at3->audio_format != 0x0270) {
        fprintf(stderr, "Not ATRAC3 format\n");
        exit(1);
    }
    offset += 2;
    at3->channels = *(uint16_t*)(buffer + offset);
    offset += 2;
    at3->sample_rate = *(uint32_t*)(buffer + offset);
    offset += 4;
    at3->byte_rate = *(uint32_t*)(buffer + offset);
    offset += 4;
    at3->block_align = *(uint16_t*)(buffer + offset);
    offset += 2;
    at3->bits_per_sample = *(uint16_t*)(buffer + offset);
    offset += 2;
    at3->extra_size = *(uint16_t*)(buffer + offset);
    offset += 2;
    at3->extra_params = malloc(at3->extra_size);
    memcpy(at3->extra_params, buffer + offset, at3->extra_size);
    offset += at3->extra_size;

    // fact chunk
    if (memcmp(buffer + offset, "fact", 4) != 0) {
        fprintf(stderr, "Invalid fact chunk\n");
        exit(1);
    }
    offset += 4;
    uint32_t fact_size = *(uint32_t*)(buffer + offset);
    offset += 4;
    at3->num_samples = *(uint32_t*)(buffer + offset);
    offset += 4; // Skip extra

    // data chunk
    if (memcmp(buffer + offset, "data", 4) != 0) {
        fprintf(stderr, "Invalid data chunk\n");
        exit(1);
    }
    offset += 4;
    at3->data_size = *(uint32_t*)(buffer + offset);
    offset += 4;
    at3->data = malloc(at3->data_size);
    memcpy(at3->data, buffer + offset, at3->data_size);

    at3->header_size = offset - at3->data_size;
    at3->header_data = malloc(at3->header_size);
    memcpy(at3->header_data, buffer, at3->header_size);

    free(buffer);
}

void at3_print_properties(AT3File* at3) {
    printf("Audio Format Code: %u (0x%04X)\n", at3->audio_format, at3->audio_format);
    printf("Number of Channels: %u\n", at3->channels);
    printf("Sample Rate: %u Hz\n", at3->sample_rate);
    printf("Average Bytes per Second: %u\n", at3->byte_rate);
    printf("Block Align: %u\n", at3->block_align);
    printf("Bits per Sample: %u\n", at3->bits_per_sample);
    printf("Extra Param Size: %u\n", at3->extra_size);
    printf("Extra Params (hex): ");
    for (int i = 0; i < at3->extra_size; i++) {
        printf("%02x ", at3->extra_params[i]);
    }
    printf("\n");
    printf("Number of Samples: %u\n", at3->num_samples);
    printf("Data Size: %u bytes\n", at3->data_size);
}

void at3_write(AT3File* at3, const char* output_filename) {
    if (!at3->data) {
        fprintf(stderr, "No data to write\n");
        exit(1);
    }
    FILE* fp = fopen(output_filename, "wb");
    if (!fp) {
        perror("Failed to open output file");
        exit(1);
    }
    fwrite(at3->header_data, 1, at3->header_size, fp);
    uint32_t data_size_le = at3->data_size;
    fwrite(&data_size_le, sizeof(uint32_t), 1, fp);
    fwrite(at3->data, 1, at3->data_size, fp);
    fclose(fp);
}

void at3_destroy(AT3File* at3) {
    free(at3->extra_params);
    free(at3->data);
    free(at3->header_data);
    free(at3);
}

// Example usage: ./program input.at3 output.at3
int main(int argc, char** argv) {
    if (argc < 3) {
        printf("Usage: %s input.at3 output.at3\n", argv[0]);
        return 1;
    }
    AT3File* at3 = at3_create(argv[1]);
    at3_read(at3, argv[1]);
    at3_print_properties(at3);
    at3_write(at3, argv[2]);
    at3_destroy(at3);
    return 0;
}
// ===== end task-044 .AT3 =====

// ===== task-045 .ATG [C++] =====
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <regex>

class ATGFile {
private:
    std::vector<std::string> imports;
    std::string compilerName;
    std::string globalFieldsAndMethods;
    bool ignoreCase;
    std::map<std::string, std::string> characterSets;
    std::map<std::string, std::string> tokens;
    std::vector<std::string> pragmas;
    std::vector<std::string> comments;
    std::string ignore;
    std::map<std::string, std::string> productions;
    std::string endName;

public:
    ATGFile(const std::string& filepath = "") {
        ignoreCase = false;
        if (!filepath.empty()) {
            read(filepath);
        }
    }

    void read(const std::string& filepath) {
        std::ifstream file(filepath);
        if (!file.is_open()) {
            std::cerr << "Failed to open file." << std::endl;
            return;
        }
        std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
        file.close();

        std::istringstream iss(content);
        std::string line;
        std::string state = "imports";
        while (std::getline(iss, line)) {
            line = std::regex_replace(line, std::regex("^\\s+|\\s+$"), "");
            if (line.empty()) continue;

            std::smatch match;
            if (state == "imports" && (std::regex_search(line, std::regex("^using ")) || std::regex_search(line, std::regex("^import ")))) {
                imports.push_back(line);
            } else if (std::regex_match(line, match, std::regex("^COMPILER\\s*(.*)"))) {
                compilerName = match[1];
                state = "global";
            } else if (state == "global" && !std::regex_search(line, std::regex("^(IGNORECASE|CHARACTERS|TOKENS|PRAGMAS|COMMENTS|IGNORE|PRODUCTIONS|END)"))) {
                globalFieldsAndMethods += line + "\n";
            } else if (line == "IGNORECASE") {
                ignoreCase = true;
                state = "scanner";
            } else if (std::regex_search(line, std::regex("^CHARACTERS"))) {
                state = "characters";
            } else if (state == "characters" && line.find('=') != std::string::npos) {
                size_t pos = line.find('=');
                std::string name = line.substr(0, pos);
                std::string defn = line.substr(pos + 1);
                name = std::regex_replace(name, std::regex("^\\s+|\\s+$"), "");
                defn = std::regex_replace(defn, std::regex("^\\s+|\\s+$|\\.$"), "");
                characterSets[name] = defn;
            } else if (std::regex_search(line, std::regex("^TOKENS"))) {
                state = "tokens";
            } else if (state == "tokens" && line.find('=') != std::string::npos) {
                size_t pos = line.find('=');
                std::string name = line.substr(0, pos);
                std::string defn = line.substr(pos + 1);
                name = std::regex_replace(name, std::regex("^\\s+|\\s+$"), "");
                defn = std::regex_replace(defn, std::regex("^\\s+|\\s+$|\\.$"), "");
                tokens[name] = defn;
            } else if (std::regex_search(line, std::regex("^PRAGMAS"))) {
                state = "pragmas";
            } else if (state == "pragmas" && line.find('=') != std::string::npos) {
                pragmas.push_back(std::regex_replace(line, std::regex("\\.$"), ""));
            } else if (std::regex_search(line, std::regex("^COMMENTS FROM"))) {
                comments.push_back(line);
            } else if (std::regex_match(line, match, std::regex("^IGNORE\\s*(.*)"))) {
                ignore = match[1];
            } else if (std::regex_search(line, std::regex("^PRODUCTIONS"))) {
                state = "productions";
            } else if (state == "productions" && line.find('=') != std::string::npos) {
                size_t pos = line.find('=');
                std::string name = line.substr(0, pos);
                std::string defn = line.substr(pos + 1);
                name = std::regex_replace(name, std::regex("^\\s+|\\s+$"), "");
                defn = std::regex_replace(defn, std::regex("^\\s+|\\s+$|\\.$"), "");
                productions[name] = defn;
            } else if (std::regex_match(line, match, std::regex("^END\\s*(.*)\\.$"))) {
                endName = match[1];
                state = "end";
            }
        }
    }

    void printProperties() {
        std::cout << "{\n";
        std::cout << "  \"imports\": [";
        for (size_t i = 0; i < imports.size(); ++i) {
            std::cout << "\"" << imports[i] << "\"" << (i < imports.size() - 1 ? ", " : "");
        }
        std::cout << "],\n";
        std::cout << "  \"compilerName\": \"" << compilerName << "\",\n";
        std::cout << "  \"globalFieldsAndMethods\": \"" << globalFieldsAndMethods << "\",\n";
        std::cout << "  \"ignoreCase\": " << (ignoreCase ? "true" : "false") << ",\n";
        std::cout << "  \"characterSets\": {";
        for (auto it = characterSets.begin(); it != characterSets.end(); ) {
            std::cout << "\"" << it->first << "\": \"" << it->second << "\"";
            if (++it != characterSets.end()) std::cout << ", ";
        }
        std::cout << "},\n";
        std::cout << "  \"tokens\": {";
        for (auto it = tokens.begin(); it != tokens.end(); ) {
            std::cout << "\"" << it->first << "\": \"" << it->second << "\"";
            if (++it != tokens.end()) std::cout << ", ";
        }
        std::cout << "},\n";
        std::cout << "  \"pragmas\": [";
        for (size_t i = 0; i < pragmas.size(); ++i) {
            std::cout << "\"" << pragmas[i] << "\"" << (i < pragmas.size() - 1 ? ", " : "");
        }
        std::cout << "],\n";
        std::cout << "  \"comments\": [";
        for (size_t i = 0; i < comments.size(); ++i) {
            std::cout << "\"" << comments[i] << "\"" << (i < comments.size() - 1 ? ", " : "");
        }
        std::cout << "],\n";
        std::cout << "  \"ignore\": \"" << ignore << "\",\n";
        std::cout << "  \"productions\": {";
        for (auto it = productions.begin(); it != productions.end(); ) {
            std::cout << "\"" << it->first << "\": \"" << it->second << "\"";
            if (++it != productions.end()) std::cout << ", ";
        }
        std::cout << "},\n";
        std::cout << "  \"endName\": \"" << endName << "\"\n";
        std::cout << "}\n";
    }

    void write(const std::string& filepath) {
        std::ofstream file(filepath);
        if (!file.is_open()) {
            std::cerr << "Failed to open file for writing." << std::endl;
            return;
        }
        for (const auto& imp : imports) {
            file << imp << "\n";
        }
        file << "COMPILER " << compilerName << "\n";
        file << globalFieldsAndMethods;
        if (ignoreCase) file << "IGNORECASE\n";
        file << "CHARACTERS\n";
        for (const auto& entry : characterSets) {
            file << "  " << entry.first << " = " << entry.second << ".\n";
        }
        file << "TOKENS\n";
        for (const auto& entry : tokens) {
            file << "  " << entry.first << " = " << entry.second << ".\n";
        }
        if (!pragmas.empty()) {
            file << "PRAGMAS\n";
            for (const auto& pragma : pragmas) {
                file << "  " << pragma << ".\n";
            }
        }
        for (const auto& comment : comments) {
            file << comment << "\n";
        }
        if (!ignore.empty()) file << "IGNORE " << ignore << "\n";
        file << "PRODUCTIONS\n";
        for (const auto& entry : productions) {
            file << "  " << entry.first << " = " << entry.second << ".\n";
        }
        file << "END " << endName << ".\n";
        file.close();
    }
};

