// ===== task-065 .BMP [C++] =====
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <cstdint>
#include <cstring>

class BMPHandler {
private:
    std::vector<uint8_t> data;
    std::map<std::string, int64_t> properties; // Using int64_t for generality

    void decodeProperties() {
        // Helper to read little-endian values
        auto readUint16 = [&](size_t offset) { return static_cast<uint16_t>(data[offset] | (data[offset + 1] << 8)); };
        auto readInt32 = [&](size_t offset) { return static_cast<int32_t>(data[offset] | (data[offset + 1] << 8) | (data[offset + 2] << 16) | (data[offset + 3] << 24)); };
        auto readUint32 = [&](size_t offset) { return static_cast<uint32_t>(readInt32(offset)); };

        // Bitmap File Header
        char sig[3] = {static_cast<char>(data[0]), static_cast<char>(data[1]), '\0'};
        properties["Signature"] = *reinterpret_cast<int64_t*>(sig); // For display, but treat as string later
        properties["File Size"] = readUint32(2);
        properties["Reserved 1"] = readUint16(6);
        properties["Reserved 2"] = readUint16(8);
        properties["Pixel Array Offset"] = readUint32(10);

        // DIB Header
        uint32_t dibSize = readUint32(14);
        properties["DIB Header Size"] = dibSize;
        properties["Width"] = readInt32(18);
        properties["Height"] = readInt32(22);
        properties["Color Planes"] = readUint16(26);
        properties["Bits Per Pixel"] = readUint16(28);
        properties["Compression Method"] = readUint32(30);
        properties["Raw Image Size"] = readUint32(34);
        properties["Horizontal Resolution"] = readInt32(38);
        properties["Vertical Resolution"] = readInt32(42);
        properties["Palette Colors"] = readUint32(46);
        properties["Important Colors"] = readUint32(50);

        if (dibSize >= 108) { // Version 4+
            properties["Red Mask"] = readUint32(54);
            properties["Green Mask"] = readUint32(58);
            properties["Blue Mask"] = readUint32(62);
            properties["Alpha Mask"] = readUint32(66);
            properties["Color Space Type"] = readUint32(70);
            // Additional fields can be added
        }
        if (dibSize >= 124) { // Version 5+
            properties["Intent"] = readUint32(122);
            properties["Profile Data Offset"] = readUint32(126);
            properties["Profile Size"] = readUint32(130);
        }
    }

public:
    BMPHandler(const std::string& filepath) {
        std::ifstream file(filepath, std::ios::binary | std::ios::ate);
        if (!file) {
            throw std::runtime_error("Failed to open file");
        }
        size_t size = file.tellg();
        file.seekg(0);
        data.resize(size);
        file.read(reinterpret_cast<char*>(data.data()), size);
        decodeProperties();
    }

    void printProperties() {
        for (const auto& pair : properties) {
            if (pair.first == "Signature") {
                char sig[3];
                memcpy(sig, &pair.second, 2);
                sig[2] = '\0';
                std::cout << pair.first << ": " << sig << std::endl;
            } else {
                std::cout << pair.first << ": " << pair.second << std::endl;
            }
        }
    }

    void write(const std::string& outputPath) {
        std::ofstream file(outputPath, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Failed to write file");
        }
        file.write(reinterpret_cast<const char*>(data.data()), data.size());
    }
};
// ===== end task-065 .BMP =====

// ===== task-066 .BPS [C++] =====
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <iomanip>
#include <map>

class BPSFile {
private:
    std::vector<unsigned char> data;
    std::map<std::string, std::string> properties; // Simplified to strings for printing
    std::vector<std::map<std::string, std::string>> actions;

    std::pair<long long, size_t> decodeVLI(size_t pos) {
        long long value = 0;
        long long shift = 1;
        while (true) {
            unsigned char x = data[pos++];
            value += (x & 0x7f) * shift;
            if (x & 0x80) break;
            shift <<= 7;
            value += shift;
        }
        return {value, pos};
    }

    std::pair<long long, size_t> decodeSignedVLI(size_t pos) {
        auto res = decodeVLI(pos);
        long long value = res.first;
        int sign = value & 1;
        value = (value >> 1) * (sign ? -1 : 1);
        return {value, res.second};
    }

    void readProperties() {
        size_t pos = 0;

        // Magic
        std::string magic(data.begin() + pos, data.begin() + pos + 4);
        properties["magic"] = magic;
        pos += 4;
        if (magic != "BPS1") {
            throw std::runtime_error("Invalid BPS file");
        }

        // Source size
        auto res = decodeVLI(pos);
        properties["source_size"] = std::to_string(res.first);
        pos = res.second;

        // Target size
        res = decodeVLI(pos);
        properties["target_size"] = std::to_string(res.first);
        pos = res.second;

        // Metadata size
        res = decodeVLI(pos);
        long long metadataSize = res.first;
        properties["metadata_size"] = std::to_string(metadataSize);
        pos = res.second;

        // Metadata
        std::string metadata;
        if (metadataSize > 0) {
            metadata = std::string(data.begin() + pos, data.begin() + pos + metadataSize);
            pos += metadataSize;
        }
        properties["metadata"] = metadata;

        // Actions
        size_t endActions = data.size() - 12;
        while (pos < endActions) {
            res = decodeVLI(pos);
            long long dataVal = res.first;
            pos = res.second;
            int command = dataVal & 3;
            long long length = (dataVal >> 2) + 1;
            std::map<std::string, std::string> action;
            action["type"] = std::to_string(command);
            action["length"] = std::to_string(length);

            if (command == 1) { // TargetRead
                std::stringstream ss;
                for (long long i = 0; i < length; ++i) {
                    ss << std::hex << std::setw(2) << std::setfill('0') << (int)data[pos + i];
                }
                action["data"] = ss.str();
                pos += length;
            } else if (command == 2 || command == 3) { // SourceCopy or TargetCopy
                res = decodeSignedVLI(pos);
                action["relative_offset"] = std::to_string(res.first);
                pos = res.second;
            }

            actions.push_back(action);
        }

        // Checksums
        std::stringstream ss;
        for (int i = 0; i < 4; ++i) ss << std::hex << std::setw(2) << std::setfill('0') << (int)data[pos + i];
        properties["source_checksum"] = ss.str();
        pos += 4;

        ss.str("");
        for (int i = 0; i < 4; ++i) ss << std::hex << std::setw(2) << std::setfill('0') << (int)data[pos + i];
        properties["target_checksum"] = ss.str();
        pos += 4;

        ss.str("");
        for (int i = 0; i < 4; ++i) ss << std::hex << std::setw(2) << std::setfill('0') << (int)data[pos + i];
        properties["patch_checksum"] = ss.str();
    }

public:
    BPSFile(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file) throw std::runtime_error("Cannot open file");
        data = std::vector<unsigned char>((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
        readProperties();
    }

    void printProperties() const {
        std::cout << "Magic: " << properties.at("magic") << std::endl;
        std::cout << "Source Size: " << properties.at("source_size") << std::endl;
        std::cout << "Target Size: " << properties.at("target_size") << std::endl;
        std::cout << "Metadata Size: " << properties.at("metadata_size") << std::endl;
        std::cout << "Metadata: " << properties.at("metadata") << std::endl;
        std::cout << "Actions:" << std::endl;
        const std::string types[] = {"SourceRead", "TargetRead", "SourceCopy", "TargetCopy"};
        for (size_t i = 0; i < actions.size(); ++i) {
            const auto& action = actions[i];
            int type = std::stoi(action.at("type"));
            std::cout << "  Action " << (i + 1) << ":" << std::endl;
            std::cout << "    Type: " << type << " (" << types[type] << ")" << std::endl;
            std::cout << "    Length: " << action.at("length") << std::endl;
            if (action.count("data")) std::cout << "    Data: " << action.at("data") << std::endl;
            if (action.count("relative_offset")) std::cout << "    Relative Offset: " << action.at("relative_offset") << std::endl;
        }
        std::cout << "Source Checksum: " << properties.at("source_checksum") << std::endl;
        std::cout << "Target Checksum: " << properties.at("target_checksum") << std::endl;
        std::cout << "Patch Checksum: " << properties.at("patch_checksum") << std::endl;
    }

    void write(const std::string& filename) const {
        std::ofstream file(filename, std::ios::binary);
        file.write(reinterpret_cast<const char*>(data.data()), data.size());
    }
};

