// ===== task-070 .BSP [C++] =====
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <iomanip>

struct Lump {
    int32_t fileofs;
    int32_t filelen;
    int32_t lumpVersion;
    char fourCC[4];
};

class BSPFile {
private:
    std::string ident;
    int32_t version;
    std::vector<Lump> lumps;
    int32_t mapRevision;
    std::string filename;

public:
    BSPFile(const std::string& fn = "") : version(0), mapRevision(0), filename(fn) {
        lumps.resize(64);
        ident = "VBSP";
        if (!fn.empty()) {
            read(fn);
        }
    }

    void read(const std::string& fn) {
        std::ifstream file(fn, std::ios::binary);
        if (!file) {
            std::cerr << "Failed to open file." << std::endl;
            return;
        }
        char buffer[1036];
        file.read(buffer, 1036);

        // Read ident
        ident.assign(buffer, 4);

        // Read version
        std::memcpy(&version, buffer + 4, sizeof(int32_t));

        // Read lumps
        for (size_t i = 0; i < 64; ++i) {
            size_t offset = 8 + i * 16;
            std::memcpy(&lumps[i].fileofs, buffer + offset, sizeof(int32_t));
            std::memcpy(&lumps[i].filelen, buffer + offset + 4, sizeof(int32_t));
            std::memcpy(&lumps[i].lumpVersion, buffer + offset + 8, sizeof(int32_t));
            std::memcpy(lumps[i].fourCC, buffer + offset + 12, 4);
        }

        // Read map revision
        std::memcpy(&mapRevision, buffer + 1032, sizeof(int32_t));
    }

    void write(const std::string& fn) {
        std::ofstream file(fn, std::ios::binary);
        if (!file) {
            std::cerr << "Failed to write file." << std::endl;
            return;
        }
        char buffer[1036] = {0};

        // Write ident
        std::memcpy(buffer, ident.c_str(), 4);

        // Write version
        std::memcpy(buffer + 4, &version, sizeof(int32_t));

        // Write lumps
        for (size_t i = 0; i < 64; ++i) {
            size_t offset = 8 + i * 16;
            std::memcpy(buffer + offset, &lumps[i].fileofs, sizeof(int32_t));
            std::memcpy(buffer + offset + 4, &lumps[i].filelen, sizeof(int32_t));
            std::memcpy(buffer + offset + 8, &lumps[i].lumpVersion, sizeof(int32_t));
            std::memcpy(buffer + offset + 12, lumps[i].fourCC, 4);
        }

        // Write map revision
        std::memcpy(buffer + 1032, &mapRevision, sizeof(int32_t));

        file.write(buffer, 1036);
        // Note: Header only; lump data not written.
    }

    void printProperties() const {
        std::cout << "Identification: " << ident << std::endl;
        std::cout << "Version: " << version << std::endl;
        std::cout << "Lumps:" << std::endl;
        for (size_t i = 0; i < 64; ++i) {
            std::cout << "Lump " << i << ": Offset=" << lumps[i].fileofs
                      << ", Length=" << lumps[i].filelen
                      << ", Version=" << lumps[i].lumpVersion
                      << ", FourCC='";
            for (int j = 0; j < 4; ++j) {
                char c = lumps[i].fourCC[j];
                if (c >= 32 && c <= 126) {
                    std::cout << c;
                } else {
                    std::cout << "\\x" << std::hex << std::setw(2) << std::setfill('0') << (int)(unsigned char)c;
                }
            }
            std::cout << "'" << std::endl;
        }
        std::cout << "Map Revision: " << mapRevision << std::endl;
    }
};

int main(int argc, char* argv[]) {
    if (argc > 1) {
        BSPFile bsp(argv[1]);
        bsp.printProperties();
    }
    return 0;
}
// ===== end task-070 .BSP =====

// ===== task-071 .BYU [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 1024
#define MAX_PARTS 100
#define MAX_POINTS 10000
#define MAX_POLYS 10000

typedef struct {
    int nparts;
    int npoints;
    int npolys;
    int nconnects;
    int ntest;
    int parts[MAX_PARTS][2];
    double points[MAX_POINTS][3];
    int polygons[MAX_POLYS][20];  // Assume max 20 sides per poly
    int poly_sizes[MAX_POLYS];
} BYUFile;

void read_byu(BYUFile *byu, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening file");
        return;
    }

    char line[MAX_LINE];
    fgets(line, MAX_LINE, fp);
    sscanf(line, "%d %d %d %d %d", &byu->nparts, &byu->npoints, &byu->npolys, &byu->nconnects, &byu->ntest);

    for (int i = 0; i < byu->nparts; i++) {
        fgets(line, MAX_LINE, fp);
        sscanf(line, "%d %d", &byu->parts[i][0], &byu->parts[i][1]);
    }

    int point_idx = 0;
    while (point_idx < byu->npoints) {
        fgets(line, MAX_LINE, fp);
        char *token = strtok(line, " ");
        while (token && point_idx < byu->npoints) {
            sscanf(token, "%lf", &byu->points[point_idx][0]);
            token = strtok(NULL, " ");
            sscanf(token, "%lf", &byu->points[point_idx][1]);
            token = strtok(NULL, " ");
            sscanf(token, "%lf", &byu->points[point_idx][2]);
            point_idx++;
            token = strtok(NULL, " ");
        }
    }

    int poly_idx = 0;
    while (poly_idx < byu->npolys) {
        int size = 0;
        while (1) {
            if (!fgets(line, MAX_LINE, fp)) break;
            char *token = strtok(line, " ");
            while (token) {
                int conn;
                sscanf(token, "%d", &conn);
                if (conn < 0) {
                    byu->polygons[poly_idx][size++] = -conn;
                    break;
                }
                byu->polygons[poly_idx][size++] = conn;
                token = strtok(NULL, " ");
            }
            if (size > 0 && byu->polygons[poly_idx][size-1] > 0) continue;
            break;
        }
        byu->poly_sizes[poly_idx] = size;
        poly_idx++;
    }
    fclose(fp);
    print_properties(byu);
}

void print_properties(BYUFile *byu) {
    printf("Header Properties:\n");
    printf("- nparts: %d\n", byu->nparts);
    printf("- npoints: %d\n", byu->npoints);
    printf("- npolys: %d\n", byu->npolys);
    printf("- nconnects: %d\n", byu->nconnects);
    printf("- ntest: %d\n", byu->ntest);
    printf("\nPart Boundaries:\n");
    for (int i = 0; i < byu->nparts; i++) {
        printf("- Part %d: first=%d, last=%d\n", i+1, byu->parts[i][0], byu->parts[i][1]);
    }
    printf("\nVertex Coordinates:\n");
    for (int i = 0; i < byu->npoints; i++) {
        printf("Point %d: [%.5e, %.5e, %.5e]\n", i+1, byu->points[i][0], byu->points[i][1], byu->points[i][2]);
    }
    printf("\nPolygons:\n");
    for (int i = 0; i < byu->npolys; i++) {
        printf("Polygon %d: ", i+1);
        for (int j = 0; j < byu->poly_sizes[i]; j++) {
            printf("%d ", byu->polygons[i][j]);
        }
        printf("\n");
    }
}

void write_byu(BYUFile *byu, const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("Error opening file for write");
        return;
    }
    fprintf(fp, "%8d%8d%8d%8d%8d\n", byu->nparts, byu->npoints, byu->npolys, byu->nconnects, byu->ntest);
    for (int i = 0; i < byu->nparts; i++) {
        fprintf(fp, "%8d%8d\n", byu->parts[i][0], byu->parts[i][1]);
    }
    for (int i = 0; i < byu->npoints; i++) {
        fprintf(fp, "%12.5e%12.5e%12.5e", byu->points[i][0], byu->points[i][1], byu->points[i][2]);
        if ((i + 1) % 2 == 0) fprintf(fp, "\n");
    }
    if (byu->npoints % 2 != 0) fprintf(fp, "\n");
    for (int i = 0; i < byu->npolys; i++) {
        for (int j = 0; j < byu->poly_sizes[i]; j++) {
            int idx = byu->polygons[i][j];
            if (j == byu->poly_sizes[i] - 1) {
                fprintf(fp, "%6d ", -idx);
            } else {
                fprintf(fp, "%6d ", idx);
            }
            if ((j + 1) % 16 == 0) fprintf(fp, "\n");
        }
        fprintf(fp, "\n");
    }
    fclose(fp);
}

