// ===== task-089 .CIF [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>  // For regex, or implement simple matching

// Structs for properties
typedef struct {
    int line;
    char* content;
} Comment;

typedef struct {
    char* name;
    int line;
    // Items: simple map simulation with arrays
    char** tags;
    char** values;
    int item_count;
    // Loops and frames simplified as counts for demo
    int loop_count;
    int save_frame_count;
} Block;

typedef struct {
    Block* data_blocks;
    int block_count;
    Comment* comments;
    int comment_count;
    char** errors;
    int error_count;
} CIFProperties;

// Function prototypes
CIFProperties* read_cif(const char* filename);
void print_properties(CIFProperties* props);
void write_cif(CIFProperties* props, const char* output_filename);
void free_properties(CIFProperties* props);
char* value_to_str(const char* val_type, const char* val);  // Simplistic

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input.cif> [output.cif]\n", argv[0]);
        return 1;
    }
    CIFProperties* props = read_cif(argv[1]);
    print_properties(props);
    if (argc > 2) {
        write_cif(props, argv[2]);
    }
    free_properties(props);
    return 0;
}

CIFProperties* read_cif(const char* filename) {
    CIFProperties* props = malloc(sizeof(CIFProperties));
    props->block_count = 0;
    props->comment_count = 0;
    props->error_count = 0;
    props->data_blocks = NULL;
    props->comments = NULL;
    props->errors = NULL;

    FILE* file = fopen(filename, "r");
    if (!file) {
        char* err = malloc(100);
        snprintf(err, 100, "File not found: %s", filename);
        props->errors = realloc(props->errors, sizeof(char*) * (props->error_count + 1));
        props->errors[props->error_count++] = err;
        return props;
    }

    Block* current_block = NULL;
    int max_blocks = 10;  // Arbitrary max
    props->data_blocks = malloc(sizeof(Block) * max_blocks);
    char line[1024];
    int line_num = 0;
    int in_loop = 0;

    while (fgets(line, sizeof(line), file)) {
        line_num++;
        char* stripped = line;
        while (*stripped == ' ' || *stripped == '\t') stripped++;  // Trim left
        char* end = stripped + strlen(stripped) - 1;
        while (end > stripped && (*end == ' ' || *end == '\t' || *end == '\n')) *end-- = '\0';

        if (stripped[0] == '#') {
            props->comments = realloc(props->comments, sizeof(Comment) * (props->comment_count + 1));
            props->comments[props->comment_count].line = line_num;
            props->comments[props->comment_count].content = strdup(stripped);
            props->comment_count++;
            continue;
        }

        // Simple string match for data_
        if (strncmp(stripped, "data_", 5) == 0 && strlen(stripped) > 5 && stripped[5] != ' ') {
            if (current_block) {
                props->data_blocks[props->block_count++] = *current_block;
                if (props->block_count >= max_blocks) max_blocks *= 2, props->data_blocks = realloc(props->data_blocks, sizeof(Block) * max_blocks);
            }
            current_block = malloc(sizeof(Block));
            current_block->name = strdup(stripped + 5);
            current_block->line = line_num;
            current_block->item_count = 0;
            current_block->tags = malloc(sizeof(char*) * 10);  // Max items
            current_block->values = malloc(sizeof(char*) * 10);
            current_block->loop_count = 0;
            current_block->save_frame_count = 0;
            in_loop = 0;
            continue;
        }

        // Similar simplistic matches for save_, loop_, items
        // For items: check if starts with _ and has space
        if (stripped[0] == '_' && strchr(stripped, ' ')) {
            char* space_pos = strchr(stripped, ' ');
            *space_pos = '\0';
            char* tag = strdup(stripped);
            char* val = strdup(space_pos + 1);
            current_block->tags[current_block->item_count] = tag;
            current_block->values[current_block->item_count] = val;
            current_block->item_count++;
            continue;
        }

        // Loop simplistic: count 'loop_' occurrences
        if (strcasestr(stripped, "loop_")) {
            current_block->loop_count++;
            in_loop = 1;
            continue;
        }

        // Comments/errors etc.
    }
    if (current_block) {
        props->data_blocks[props->block_count++] = *current_block;
        free(current_block);
    }
    fclose(file);
    return props;
}

void print_properties(CIFProperties* props) {
    printf("CIF Properties:\n");
    printf("Data Blocks: %d\n", props->block_count);
    for (int i = 0; i < props->block_count; i++) {
        printf("  Block %s: %d items, %d loops\n", props->data_blocks[i].name, props->data_blocks[i].item_count, props->data_blocks[i].loop_count);
    }
    printf("Comments: %d\n", props->comment_count);
    for (int i = 0; i < props->error_count; i++) {
        printf("Error: %s\n", props->errors[i]);
    }
    // Full dump would print all
}

void write_cif(CIFProperties* props, const char* output_filename) {
    FILE* out = fopen(output_filename, "w");
    if (!out) return;
    fprintf(out, "# Generated CIF\n");
    for (int i = 0; i < props->block_count; i++) {
        Block b = props->data_blocks[i];
        fprintf(out, "data_%s\n", b.name);
        for (int j = 0; j < b.item_count; j++) {
            fprintf(out, "_%s %s\n", b.tags[j], value_to_str("string", b.values[j]));  // Simplistic
        }
        // Loops/frames...
    }
    fclose(out);
    printf("Written to %s\n", output_filename);
}

char* value_to_str(const char* val_type, const char* val) {
    if (strcmp(val_type, "n/a") == 0) return ".";
    if (strcmp(val_type, "unknown") == 0) return "?";
    char* quoted = malloc(strlen(val) + 3);
    snprintf(quoted, strlen(val) + 3, "\"%s\"", val);
    return quoted;
}

void free_properties(CIFProperties* props) {
    for (int i = 0; i < props->block_count; i++) {
        Block b = props->data_blocks[i];
        for (int j = 0; j < b.item_count; j++) {
            free(b.tags[j]);
            free(b.values[j]);
        }
        free(b.tags);
        free(b.values);
        free(b.name);
    }
    free(props->data_blocks);
    for (int i = 0; i < props->comment_count; i++) free(props->comments[i].content);
    free(props->comments);
    for (int i = 0; i < props->error_count; i++) free(props->errors[i]);
    free(props->errors);
    free(props);
}
// ===== end task-089 .CIF =====

// ===== task-090 .CLASS [C++] =====
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint8_t *data;
    size_t offset;
    size_t size;
    int *constant_pool_tags;  // Simplified: only tags for demo
    char **constant_strings;  // Approx strings
    int cp_count;
} ClassFileParser;

uint8_t u1(ClassFileParser *p) {
    if (p->offset >= p->size) return 0;
    return p->data[p->offset++];
}

uint16_t u2(ClassFileParser *p) {
    uint16_t val = (p->data[p->offset] << 8) | p->data[p->offset + 1];
    p->offset += 2;
    return val;
}

uint32_t u4(ClassFileParser *p) {
    uint32_t val = (p->data[p->offset] << 24) | (p->data[p->offset + 1] << 16) |
                   (p->data[p->offset + 2] << 8) | p->data[p->offset + 3];
    p->offset += 4;
    return val;
}

void read_magic(ClassFileParser *p) {
    uint32_t magic = u4(p);
    if (magic != 0xCAFEBABE) {
        fprintf(stderr, "Invalid magic\n");
        exit(1);
    }
    printf("magic: 0x%08X\n", magic);
}

void read_versions(ClassFileParser *p) {
    uint16_t minor = u2(p);
    uint16_t major = u2(p);
    printf("versions: minor=%d, major=%d\n", minor, major);
}

int read_constant_pool_count(ClassFileParser *p) {
    return u2(p);
}

void read_constant_pool(ClassFileParser *p, int count) {
    p->cp_count = count;
    p->constant_pool_tags = malloc((count - 1) * sizeof(int));
    p->constant_strings = malloc((count - 1) * sizeof(char*));
    for (int i = 0; i < count - 1; i++) {
        int tag = u1(p);
        p->constant_pool_tags[i] = tag;
        p->constant_strings[i] = NULL;
        if (tag == 1) {  // Utf8 approx
            int len = u2(p);
            p->constant_strings[i] = malloc(len + 1);
            memcpy(p->constant_strings[i], &p->data[p->offset], len);
            p->constant_strings[i][len] = '\0';
            p->offset += len;
        } else if (tag == 3 || tag == 4) {
            u4(p);
        } else if (tag == 5 || tag == 6) {
            u4(p); u4(p);
            i++;  // Skip
        } else {
            u2(p);  // Approx skip
        }
    }
}

char* get_constant_string(ClassFileParser *p, int index) {
    if (index == 0) return "none";
    if (index - 1 >= p->cp_count - 1 || !p->constant_strings[index - 1]) {
        char buf[32];
        sprintf(buf, "CONSTANT[%d]", index);
        return strdup(buf);
    }
    return strdup(p->constant_strings[index - 1]);
}

void read_access_flags(ClassFileParser *p) {
    uint16_t flags = u2(p);
    printf("access_flags: 0x%04X\n", flags);
}

void read_this_class(ClassFileParser *p) {
    int idx = u2(p);
    printf("this_class: %s\n", get_constant_string(p, idx));
}

void read_super_class(ClassFileParser *p) {
    int idx = u2(p);
    printf("super_class: %s\n", get_constant_string(p, idx));
}

void read_interfaces(ClassFileParser *p) {
    int count = u2(p);
    printf("interfaces_count: %d\n", count);
    for (int i = 0; i < count; i++) {
        int idx = u2(p);
        printf("  interface: %s\n", get_constant_string(p, idx));
    }
}

void read_fields(ClassFileParser *p) {
    int count = u2(p);
    printf("fields_count: %d\n", count);
    for (int i = 0; i < count; i++) {
        uint16_t acc = u2(p);
        int name_idx = u2(p);
        int desc_idx = u2(p);
        u2(p);  // attributes_count, skip
        printf("  field: access=0x%04X, name=%s, descriptor=%s\n", acc, get_constant_string(p, name_idx), get_constant_string(p, desc_idx));
        // Skip attributes
    }
}

void read_methods(ClassFileParser *p) {
    int count = u2(p);
    printf("methods_count: %d\n", count);
    for (int i = 0; i < count; i++) {
        uint16_t acc = u2(p);
        int name_idx = u2(p);
        int desc_idx = u2(p);
        u2(p);  // attributes_count, skip
        printf("  method: access=0x%04X, name=%s, descriptor=%s\n", acc, get_constant_string(p, name_idx), get_constant_string(p, desc_idx));
        // Skip attributes
    }
}

void read_attributes_count(ClassFileParser *p) {
    int count = u2(p);
    printf("attributes_count: %d\n", count);
    // Skip
}

void parse(ClassFileParser *p) {
    read_magic(p);
    read_versions(p);
    int cp_count = read_constant_pool_count(p);
    read_constant_pool(p, cp_count);
    read_access_flags(p);
    read_this_class(p);
    read_super_class(p);
    read_interfaces(p);
    read_fields(p);
    read_methods(p);
    read_attributes_count(p);
}

void write(ClassFileParser *p, const char *filename) {
    FILE *f = fopen(filename, "wb");
    if (f) {
        fwrite(p->data, 1, p->size, f);
        fclose(f);
    }
}

void free_parser(ClassFileParser *p) {
    if (p->data) free(p->data);
    if (p->constant_pool_tags) free(p->constant_pool_tags);
    if (p->constant_strings) {
        for (int i = 0; i < p->cp_count - 1; i++) {
            if (p->constant_strings[i]) free(p->constant_strings[i]);
        }
        free(p->constant_strings);
    }
    free(p);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: ./parser <file.class>\n");
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("Open file");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    size_t size = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    ClassFileParser p = { .data = data, .offset = 0, .size = size };
    parse(&p);
    // write(&p, "output.class");
    free_parser(&p);
    return 0;
}
// ===== end task-090 .CLASS =====

// ===== task-091 .CLS [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 1024
#define MAX_CLASSES 100
#define MAX_SAMPLES 10000

typedef struct {
    char filename[256];
    char file_type[32];
    int num_samples;
    int num_classes;
    char class_names[MAX_CLASSES][256];
    int num_class_names;
    int phenotype_labels[MAX_SAMPLES];
    int num_labels;
} CLSProperties;

void init_properties(CLSProperties *props) {
    strcpy(props->file_type, "");
    props->num_samples = 0;
    props->num_classes = 0;
    props->num_class_names = 0;
    props->num_labels = 0;
    strcpy(props->filename, "");
}

int parse_file(const char *filename, CLSProperties *props) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("File not found");
        return 0;
    }

    char line[MAX_LINE];
    char *lines[3];
    int line_count = 0;

    // Read first three lines
    while (line_count < 3 && fgets(line, sizeof(line), file)) {
        line[strcspn(line, "\n")] = 0;  // Remove newline
        if (strlen(line) > 0) {
            lines[line_count] = strdup(line);
            line_count++;
        }
    }
    fclose(file);

    if (line_count < 3) {
        fprintf(stderr, "Invalid CLS file: insufficient lines.\n");
        return 0;
    }

    // Parse first line
    int parts[3];
    if (sscanf(lines[0], "%d %d %d", &parts[0], &parts[1], &parts[2]) != 3 || parts[2] != 1) {
        strcpy(props->file_type, "continuous or invalid");
        strcpy(props->filename, filename);
        return 1;  // Partial success
    }

    strcpy(props->file_type, "categorical");
    props->num_samples = parts[0];
    props->num_classes = parts[1];

    // Parse second line
    if (strncmp(lines[1], "# ", 2) != 0) {
        fprintf(stderr, "Invalid second line.\n");
        return 0;
    }
    char *name_start = lines[1] + 2;
    props->num_class_names = 0;
    char *token = strtok(name_start, " \t");
    while (token && props->num_class_names < MAX_CLASSES) {
        strncpy(props->class_names[props->num_class_names], token, 255);
        props->class_names[props->num_class_names][255] = 0;
        props->num_class_names++;
        token = strtok(NULL, " \t");
    }

    // Parse third line
    props->num_labels = 0;
    char *label_start = lines[1];  // Reuse for simplicity; in full impl, read properly
    token = strtok(lines[2], " \t");
    while (token && props->num_labels < MAX_SAMPLES) {
        props->phenotype_labels[props->num_labels] = atoi(token);
        props->num_labels++;
        token = strtok(NULL, " \t");
    }

    if (props->num_labels != props->num_samples || props->num_class_names != props->num_classes) {
        fprintf(stderr, "Mismatch in counts.\n");
        return 0;
    }

    strcpy(props->filename, filename);
    return 1;
}

void print_properties(const CLSProperties *props) {
    printf("File Type: %s\n", props->file_type);
    if (strcmp(props->file_type, "categorical") == 0) {
        printf("Number of Samples: %d\n", props->num_samples);
        printf("Number of Classes: %d\n", props->num_classes);
        printf("Class Names: ");
        for (int i = 0; i < props->num_class_names; i++) {
            printf("%s", props->class_names[i]);
            if (i < props->num_class_names - 1) printf(", ");
        }
        printf("\n");
        printf("Phenotype Labels: [");
        for (int i = 0; i < props->num_labels; i++) {
            printf("%d", props->phenotype_labels[i]);
            if (i < props->num_labels - 1) printf(", ");
        }
        printf("]\n");
    } else {
        printf("Note: Continuous format detected.\n");
    }
}

int write_file(const char *filename, const CLSProperties *props) {
    if (strcmp(props->file_type, "categorical") != 0) {
        fprintf(stderr, "Write supports categorical only.\n");
        return 0;
    }

    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Write failed");
        return 0;
    }

    fprintf(file, "%d %d 1\n", props->num_samples, props->num_classes);
    fprintf(file, "# ");
    for (int i = 0; i < props->num_class_names; i++) {
        fprintf(file, "%s", props->class_names[i]);
        if (i < props->num_class_names - 1) fprintf(file, " ");
    }
    fprintf(file, "\n");
    for (int i = 0; i < props->num_labels; i++) {
        fprintf(file, "%d", props->phenotype_labels[i]);
        if (i < props->num_labels - 1) fprintf(file, " ");
    }
    fprintf(file, "\n");

    fclose(file);
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    CLSProperties props;
    init_properties(&props);

    if (!parse_file(argv[1], &props)) {
        fprintf(stderr, "Parse failed.\n");
        return 1;
    }

    print_properties(&props);

    // Example write to output.cls
    write_file("output.cls", &props);

    return 0;
}
// ===== end task-091 .CLS =====

// ===== task-092 .CMD [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define HEADER_SIZE 128
#define NUM_GROUPS 8
#define GROUP_DESC_SIZE 9
#define PARAGRAPH_SIZE 16

typedef struct {
    uint8_t type;
    uint16_t length;  // in paragraphs
    uint16_t base_addr;
    uint16_t min_size;
    uint16_t max_size;
} GroupDesc;

typedef struct {
    GroupDesc groups[NUM_GROUPS];
    uint16_t rsx_index;
    uint16_t fixups_offset;
    uint8_t flags;
    uint8_t first_type;
    size_t file_size;
    uint8_t* header;
    uint8_t** group_data;
} CMDProperties;

const char* get_type_name(uint8_t type) {
    switch (type) {
        case 1: return "Code";
        case 2: return "Data";
        case 3: return "Extra Data";
        case 4: return "Stack";
        case 5: return "Aux1"; case 6: return "Aux2";
        case 7: return "Aux3"; case 8: return "Aux4";
        case 9: return "Shared Code";
        default: return "Unknown/Unused";
    }
}

void parse_flags(uint8_t flags, char* details, size_t buf_size) {
    details[0] = '\0';
    char* ptr = details;
    size_t len = 0;
    if (flags & 0x80) { len = snprintf(ptr, buf_size - len, "Perform fixups; "); ptr += len; }
    if (flags & 0x40) { len = snprintf(ptr, buf_size - len, "Allocate imaginary 8087; "); ptr += len; }
    if (flags & 0x20) { len = snprintf(ptr, buf_size - len, "Allocate 8087 if present; "); ptr += len; }
    if (flags & 0x10) { len = snprintf(ptr, buf_size - len, "This is an RSX; "); ptr += len; }
    if (details[0] == '\0') strcpy(details, "None");
}

void print_properties(CMDProperties* props) {
    printf("=== .CMD File Properties ===\n");
    printf("File Size: %zu bytes\n", props->file_size);
    printf("Header Size: 128 bytes\n\n");
    printf("Group Descriptors:\n");
    for (int i = 0; i < NUM_GROUPS; i++) {
        GroupDesc* g = &props->groups[i];
        printf("  Group %d: Type=%u (%s), Length=%u bytes, Base=%u paragraphs, Min=%u paragraphs, Max=%u paragraphs\n",
               i + 1, g->type, get_type_name(g->type), g->length * PARAGRAPH_SIZE, g->base_addr, g->min_size, g->max_size);
    }
    printf("\nRSX Index Record Offset: %u (128-byte records)\n", props->rsx_index);
    printf("Fixups Record Offset: %u (128-byte records)\n", props->fixups_offset);
    char flags_details[256];
    parse_flags(props->flags, flags_details, sizeof(flags_details));
    printf("\nFlags (0x%02X): %s\n", props->flags, flags_details);
    printf("\nValidation: First byte (type) = %u (valid if 1-9)\n", props->first_type);
}

CMDProperties* read_cmd(const char* filename) {
    FILE* f = fopen(filename, "rb");
    if (!f) {
        perror("Error opening file");
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    size_t file_size = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* data = malloc(file_size);
    fread(data, 1, file_size, f);
    fclose(f);
    if (file_size < HEADER_SIZE) {
        free(data);
        fprintf(stderr, "Invalid .CMD file: too small.\n");
        return NULL;
    }
    CMDProperties* props = malloc(sizeof(CMDProperties));
    props->header = malloc(HEADER_SIZE);
    memcpy(props->header, data, HEADER_SIZE);
    props->group_data = malloc(NUM_GROUPS * sizeof(uint8_t*));
    uint8_t* header_view = props->header;
    size_t offset = HEADER_SIZE;
    for (int i = 0; i < NUM_GROUPS; i++) {
        size_t base = i * GROUP_DESC_SIZE;
        props->groups[i].type = header_view[base];
        props->groups[i].length = *(uint16_t*)(header_view + base + 1);  // Assume little-endian
        props->groups[i].base_addr = *(uint16_t*)(header_view + base + 3);
        props->groups[i].min_size = *(uint16_t*)(header_view + base + 5);
        props->groups[i].max_size = *(uint16_t*)(header_view + base + 7);
        size_t group_size = props->groups[i].length * PARAGRAPH_SIZE;
        if (offset + group_size > file_size) group_size = file_size - offset;
        props->group_data[i] = malloc(group_size);
        memcpy(props->group_data[i], data + offset, group_size);
        offset += group_size;
    }
    props->rsx_index = *(uint16_t*)(header_view + 123);
    props->fixups_offset = *(uint16_t*)(header_view + 125);
    props->flags = header_view[127];
    props->first_type = header_view[0];
    props->file_size = file_size;
    free(data);
    print_properties(props);
    return props;
}

void write_cmd(CMDProperties* props, const char* output_filename) {
    FILE* f = fopen(output_filename, "wb");
    if (!f) {
        perror("Error writing file");
        return;
    }
    fwrite(props->header, 1, HEADER_SIZE, f);
    for (int i = 0; i < NUM_GROUPS; i++) {
        if (props->group_data[i]) {
            fwrite(props->group_data[i], 1, props->groups[i].length * PARAGRAPH_SIZE, f);  // Simplified
        }
    }
    fclose(f);
    printf("Wrote reconstructed .CMD to %s\n", output_filename);
}

void free_props(CMDProperties* props) {
    free(props->header);
    for (int i = 0; i < NUM_GROUPS; i++) {
        free(props->group_data[i]);
    }
    free(props->group_data);
    free(props);
}

int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file.cmd>\n", argv[0]);
        return 1;
    }
    CMDProperties* props = read_cmd(argv[1]);
    if (props) {
        write_cmd(props, "output.cmd");
        free_props(props);
    }
    return 0;
}
// ===== end task-092 .CMD =====

// ===== task-093 .CML [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "cJSON.h"  // Assume cJSON.h and lib is available

typedef struct {
    char* file_path;
    cJSON* data;
} CMLHandler;

CMLHandler* cml_handler_new(const char* file_path) {
    CMLHandler* handler = malloc(sizeof(CMLHandler));
    handler->file_path = strdup(file_path);
    handler->data = NULL;
    return handler;
}

void cml_handler_free(CMLHandler* handler) {
    if (handler) {
        free(handler->file_path);
        if (handler->data) cJSON_Delete(handler->data);
        free(handler);
    }
}

void print_properties(cJSON* obj, const char* path) {
    if (!obj) return;
    if (cJSON_IsObject(obj)) {
        cJSON* item = NULL;
        cJSON_ArrayForEach(item, obj) {
            char* full_path = malloc(strlen(path) + strlen(item->string) + 2);
            sprintf(full_path, "%s.%s", path, item->string);
            if (strcmp(path, "root") == 0) {
                strcpy(full_path, item->string);
            }
            printf("%s: %s\n", full_path, cJSON_GetTypeName(item));
            if (cJSON_IsObject(item) || cJSON_IsArray(item)) {
                print_properties(item, full_path);
            }
            free(full_path);
        }
    } else if (cJSON_IsArray(obj)) {
        int i = 0;
        cJSON* item = NULL;
        cJSON_ArrayForEach(item, obj) {
            char full_path[1024];
            sprintf(full_path, "%s[%d]", path, i++);
            printf("%s: %s\n", full_path, cJSON_GetTypeName(item));
            if (cJSON_IsObject(item) || cJSON_IsArray(item)) {
                print_properties(item, full_path);
            }
        }
    } else {
        printf("%s: %s (%s)\n", path, cJSON_PrintUnformatted(obj), cJSON_GetTypeName(obj));
    }
}

int read_and_decode(CMLHandler* handler) {
    FILE* f = fopen(handler->file_path, "r");
    if (!f) {
        fprintf(stderr, "File not found: %s\n", handler->file_path);
        return -1;
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* content = malloc(len + 1);
    fread(content, 1, len, f);
    content[len] = '\0';
    fclose(f);

    handler->data = cJSON_Parse(content);
    free(content);
    if (!handler->data) {
        fprintf(stderr, "Error decoding CML\n");
        return -1;
    }
    print_properties(handler->data, "root");
    return 0;
}

void write(CMLHandler* handler, const char* output_path) {
    if (!handler->data) {
        fprintf(stderr, "No data loaded\n");
        return;
    }
    char* json_str = cJSON_Print(handler->data);
    FILE* f = fopen(output_path, "w");
    if (f) {
        fputs(json_str, f);
        fclose(f);
        printf("Wrote to %s\n", output_path);
    } else {
        fprintf(stderr, "Error writing\n");
    }
    free(json_str);
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input.cml>\n", argv[0]);
        return 1;
    }
    CMLHandler* handler = cml_handler_new(argv[1]);
    if (read_and_decode(handler) == 0) {
        write(handler, "output.cml");
    }
    cml_handler_free(handler);
    return 0;
}
// ===== end task-093 .CML =====

// ===== task-094 .CMOD [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Simple structs for properties
typedef struct {
  char* key;
  void* value; // Can be float[3], float, char*
} Property;

typedef struct {
  Property* props;
  int count;
} Material;

typedef struct {
  char* semantic;
  char* format;
} VertexDesc;

typedef struct {
  char* type;
  int materialIndex;
  int indexCount;
  int* indices;
} PrimGroup;

typedef struct {
  VertexDesc* vertexDesc;
  int vertexDescCount;
  int verticesCount;
  PrimGroup* primGroups;
  int primGroupCount;
} Mesh;

typedef struct {
  Material* materials;
  int materialCount;
  Mesh* meshes;
  int meshCount;
} CMODProperties;

void initProperties(CMODProperties* props) {
  props->materials = NULL;
  props->materialCount = 0;
  props->meshes = NULL;
  props->meshCount = 0;
}

void freeProperties(CMODProperties* props) {
  // Free memory (omitted for brevity)
}

int isBinary(FILE* f) {
  char header[17];
  fseek(f, 0, SEEK_SET);
  fread(header, 16, 1, f);
  header[16] = '\0';
  if (strcmp(header, "#celmodel_binary") == 0) return 1;
  if (strcmp(header, "#celmodel__ascii") == 0) return 0;
  return -1;
}

void parseAscii(FILE* f, CMODProperties* props) {
  fseek(f, 0, SEEK_SET);
  char line[1024];
  Material* currentMaterial = NULL;
  Mesh* currentMesh = NULL;
  int inMaterial = 0, inMesh = 0, inVertexDesc = 0;
  while (fgets(line, sizeof(line), f)) {
    char* trim = strtok(line, "\n ");
    if (trim == NULL || trim[0] == '#') continue;
    if (strcmp(trim, "material") == 0) {
      props->materials = realloc(props->materials, sizeof(Material) * (++props->materialCount));
      currentMaterial = &props->materials[props->materialCount - 1];
      currentMaterial->props = NULL;
      currentMaterial->count = 0;
      inMaterial = 1;
    } else if (strcmp(trim, "end_material") == 0) {
      inMaterial = 0;
    } else if (strcmp(trim, "mesh") == 0) {
      props->meshes = realloc(props->meshes, sizeof(Mesh) * (++props->meshCount));
      currentMesh = &props->meshes[props->meshCount - 1];
      currentMesh->vertexDesc = NULL;
      currentMesh->vertexDescCount = 0;
      currentMesh->verticesCount = 0;
      currentMesh->primGroups = NULL;
      currentMesh->primGroupCount = 0;
      inMesh = 1;
    } else if (strcmp(trim, "end_mesh") == 0) {
      inMesh = 0;
    } else if (strcmp(trim, "vertexdesc") == 0) {
      inVertexDesc = 1;
    } else if (strcmp(trim, "end_vertexdesc") == 0) {
      inVertexDesc = 0;
    } else if (strcmp(trim, "vertices") == 0) {
      currentMesh->verticesCount = atoi(strtok(NULL, " "));
    } else if (strcmp(trim, "trilist") == 0 || strcmp(trim, "tristrip") == 0 || strcmp(trim, "trifan") == 0 ||
               strcmp(trim, "linelist") == 0 || strcmp(trim, "linestrip") == 0 || strcmp(trim, "pointlist") == 0 || strcmp(trim, "spritelist") == 0) {
      PrimGroup group;
      group.type = strdup(trim);
      group.materialIndex = atoi(strtok(NULL, " "));
      group.indexCount = atoi(strtok(NULL, " "));
      group.indices = malloc(sizeof(int) * group.indexCount);
      for (int i = 0; i < group.indexCount; i++) {
        group.indices[i] = atoi(strtok(NULL, " "));
      }
      currentMesh->primGroups = realloc(currentMesh->primGroups, sizeof(PrimGroup) * (++currentMesh->primGroupCount));
      currentMesh->primGroups[currentMesh->primGroupCount - 1] = group;
    } else if (inMaterial) {
      // Parse property (omitted details)
    } else if (inVertexDesc) {
      VertexDesc desc;
      desc.semantic = strdup(trim);
      desc.format = strdup(strtok(NULL, " "));
      currentMesh->vertexDesc = realloc(currentMesh->vertexDesc, sizeof(VertexDesc) * (++currentMesh->vertexDescCount));
      currentMesh->vertexDesc[currentMesh->vertexDescCount - 1] = desc;
    }
  }
}

void parseBinary(FILE* f, CMODProperties* props) {
  fseek(f, 16, SEEK_SET);
  unsigned int materialCount;
  fread(&materialCount, sizeof(unsigned int), 1, f);
  props->materials = malloc(sizeof(Material) * materialCount);
  props->materialCount = materialCount;
  for (int i = 0; i < materialCount; i++) {
    Material* mat = &props->materials[i];
    unsigned int blend;
    fread(&blend, sizeof(unsigned int), 1, f);
    // Similar for colors, floats, textures (length + chars)
    // Omitted for brevity
  }
  unsigned int meshCount;
  fread(&meshCount, sizeof(unsigned int), 1, f);
  props->meshes = malloc(sizeof(Mesh) * meshCount);
  props->meshCount = meshCount;
  for (int i = 0; i < meshCount; i++) {
    Mesh* mesh = &props->meshes[i];
    unsigned int attrCount;
    fread(&attrCount, sizeof(unsigned int), 1, f);
    mesh->vertexDesc = malloc(sizeof(VertexDesc) * attrCount);
    mesh->vertexDescCount = attrCount;
    for (int j = 0; j < attrCount; j++) {
      unsigned int semantic, format;
      fread(&semantic, sizeof(unsigned int), 1, f);
      fread(&format, sizeof(unsigned int), 1, f);
      // Map to strings if needed
    }
    fread(&mesh->verticesCount, sizeof(unsigned int), 1, f);
    // Skip vertex data
    unsigned int groupCount;
    fread(&groupCount, sizeof(unsigned int), 1, f);
    mesh->primGroups = malloc(sizeof(PrimGroup) * groupCount);
    mesh->primGroupCount = groupCount;
    for (int j = 0; j < groupCount; j++) {
      PrimGroup* group = &mesh->primGroups[j];
      unsigned int type;
      fread(&type, sizeof(unsigned int), 1, f);
      fread(&group->materialIndex, sizeof(unsigned int), 1, f);
      fread(&group->indexCount, sizeof(unsigned int), 1, f);
      group->indices = malloc(sizeof(int) * group->indexCount);
      for (int k = 0; k < group->indexCount; k++) {
        fread(&group->indices[k], sizeof(unsigned int), 1, f);
      }
    }
  }
}

void printProperties(const CMODProperties* props) {
  printf("Materials: %d\n", props->materialCount);
  // Print details
  printf("Meshes: %d\n", props->meshCount);
  for (int i = 0; i < props->meshCount; i++) {
    Mesh mesh = props->meshes[i];
    printf("Mesh %d: Vertices %d, PrimGroups %d\n", i, mesh.verticesCount, mesh.primGroupCount);
    // Print more
  }
}

void writeCMOD(const CMODProperties* props, const char* newFilepath) {
  FILE* f = fopen(newFilepath, "w");
  fprintf(f, "#celmodel__ascii\n");
  for (int i = 0; i < props->materialCount; i++) {
    fprintf(f, "material\n");
    // Write props
    fprintf(f, "end_material\n");
  }
  for (int i = 0; i < props->meshCount; i++) {
    Mesh mesh = props->meshes[i];
    fprintf(f, "mesh\n");
    fprintf(f, "vertexdesc\n");
    for (int j = 0; j < mesh.vertexDescCount; j++) {
      fprintf(f, "%s %s\n", mesh.vertexDesc[j].semantic, mesh.vertexDesc[j].format);
    }
    fprintf(f, "end_vertexdesc\n");
    fprintf(f, "vertices %d\n", mesh.verticesCount);
    // Vertex data
    for (int j = 0; j < mesh.primGroupCount; j++) {
      PrimGroup group = mesh.primGroups[j];
      fprintf(f, "%s %d %d", group.type, group.materialIndex, group.indexCount);
      for (int k = 0; k < group.indexCount; k++) {
        fprintf(f, " %d", group.indices[k]);
      }
      fprintf(f, "\n");
    }
    fprintf(f, "end_mesh\n");
  }
  fclose(f);
}

