#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <sstream>

class CPLParser {
private:
    std::string filepath;
    std::vector<std::string> headers;
    std::vector<std::vector<std::string>> data;

public:
    CPLParser(const std::string& filepath) : filepath(filepath) {}

    void read() {
        std::ifstream file(filepath);
        if (!file.is_open()) {
            std::cerr << "Error opening file" << std::endl;
            return;
        }
        std::string line;
        if (std::getline(file, line)) {
            std::stringstream ss(line);
            std::string token;
            while (std::getline(ss, token, ',')) {
                headers.push_back(token);
            }
        }
        while (std::getline(file, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string token;
            std::vector<std::string> row;
            while (std::getline(ss, token, ',')) {
                row.push_back(token);
            }
            data.push_back(row);
        }
        file.close();
    }

    void decode() {
        // Decoding is trivial for CSV
        read();
    }

    void printProperties() {
        std::cout << "Headers: ";
        for (size_t i = 0; i < headers.size(); ++i) {
            std::cout << headers[i];
            if (i < headers.size() - 1) std::cout << ", ";
        }
        std::cout << std::endl;
        for (size_t i = 0; i < data.size(); ++i) {
            std::cout << "Component " << (i + 1) << ":" << std::endl;
            for (size_t j = 0; j < headers.size(); ++j) {
                std::cout << "  " << headers[j] << ": " << (j < data[i].size() ? data[i][j] : "") << std::endl;
            }
            std::cout << std::endl;
        }
    }

    void write(const std::string& newFilepath) {
        std::ofstream file(newFilepath);
        if (!file.is_open()) {
            std::cerr << "Error opening file for writing" << std::endl;
            return;
        }
        for (size_t i = 0; i < headers.size(); ++i) {
            file << headers[i];
            if (i < headers.size() - 1) file << ",";
        }
        file << std::endl;
        for (const auto& row : data) {
            for (size_t i = 0; i < row.size(); ++i) {
                file << row[i];
                if (i < row.size() - 1) file << ",";
            }
            file << std::endl;
        }
        file.close();
    }
};

