// ===== task-138 .DIF [C++] =====
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <string>

struct PropertyEntry {
    int line;
    std::string value;
};

class DIFHandler {
private:
    std::string filename;
    int version;
    std::string title;
    int num_vectors;
    int num_tuples;
    std::map<int, std::vector<PropertyEntry>> labels;
    std::map<int, std::vector<PropertyEntry>> comments;
    std::map<int, int> sizes;
    std::map<int, int> periodicities;
    std::map<int, int> major_starts;
    std::map<int, int> minor_starts;
    std::map<int, int> true_lengths;
    std::map<int, std::string> units;
    std::map<int, std::string> display_units;

public:
    DIFHandler(const std::string& fn = "") : filename(fn), version(-1), num_vectors(-1), num_tuples(-1) {
        if (!filename.empty()) {
            read();
        }
    }

    void read() {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "File not found." << std::endl;
            return;
        }
        std::stringstream content;
        content << file.rdbuf();
        decode(content.str());
    }

    void decode(const std::string& content) {
        std::istringstream iss(content);
        std::string line;
        std::vector<std::string> lines;
        while (std::getline(iss, line)) {
            lines.push_back(line);
        }
        for (size_t i = 0; i < lines.size() && lines[i] != "DATA"; i += 3) {
            std::string topic = lines[i];
            std::string part_line = lines[i + 1];
            size_t comma_pos = part_line.find(',');
            int vector = std::stoi(part_line.substr(0, comma_pos));
            int num_value = std::stoi(part_line.substr(comma_pos + 1));
            std::string str_value = lines[i + 2];
            str_value = str_value.substr(1, str_value.size() - 2); // Remove quotes
            if (topic == "TABLE") {
                version = num_value;
                title = str_value;
            } else if (topic == "VECTORS") {
                num_vectors = num_value;
            } else if (topic == "TUPLES") {
                num_tuples = num_value;
            } else if (topic == "LABEL") {
                labels[vector].push_back({num_value, str_value});
            } else if (topic == "COMMENT") {
                comments[vector].push_back({num_value, str_value});
            } else if (topic == "SIZE") {
                sizes[vector] = num_value;
            } else if (topic == "PERIODICITY") {
                periodicities[vector] = num_value;
            } else if (topic == "MAJORSTART") {
                major_starts[vector] = num_value;
            } else if (topic == "MINORSTART") {
                minor_starts[vector] = num_value;
            } else if (topic == "TRUELENGTH") {
                true_lengths[vector] = num_value;
            } else if (topic == "UNITS") {
                units[vector] = str_value;
            } else if (topic == "DISPLAYUNITS") {
                display_units[vector] = str_value;
            }
        }
    }

    void printProperties() {
        std::cout << "version: " << version << std::endl;
        std::cout << "title: " << title << std::endl;
        std::cout << "num_vectors: " << num_vectors << std::endl;
        std::cout << "num_tuples: " << num_tuples << std::endl;
        // Print labels
        std::cout << "labels: ";
        for (const auto& pair : labels) {
            std::cout << "vector " << pair.first << ": ";
            for (const auto& entry : pair.second) {
                std::cout << "{line: " << entry.line << ", label: " << entry.value << "} ";
            }
        }
        std::cout << std::endl;
        // Similarly for other maps (omitted for brevity; implement as needed)
    }

    void write(const std::string& output_filename, const std::map<std::string, std::string>& new_properties, const std::vector<std::string>& example_data) {
        // Update properties if provided (simplified; parse new_properties as needed)
        std::ofstream file(output_filename);
        if (!file.is_open()) {
            std::cerr << "Error opening output file." << std::endl;
            return;
        }
        file << "TABLE\n";
        file << "0," << version << "\n";
        file << "\"" << title << "\"\n";
        file << "VECTORS\n";
        file << "0," << num_vectors << "\n";
        file << "\"\"\n";
        file << "TUPLES\n";
        file << "0," << num_tuples << "\n";
        file << "\"\"\n";
        // Write labels example
        for (const auto& pair : labels) {
            for (const auto& entry : pair.second) {
                file << "LABEL\n";
                file << pair.first << "," << entry.line << "\n";
                file << "\"" << entry.value << "\"\n";
            }
        }
        // Similarly for others
        file << "DATA\n";
        file << "0,0\n";
        file << "\"\"\n";
        if (!example_data.empty()) {
            file << "-1,0\n";
            file << "BOT\n";
            for (const auto& cell : example_data) {
                // Assume string for simplicity
                file << "1,0\n";
                file << "\"" << cell << "\"\n";
            }
            file << "-1,0\n";
            file << "EOD\n";
        }
        file.close();
    }
};
// ===== end task-138 .DIF =====

// ===== task-139 .DIRED [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char *directory;
    char fileType;
    char *permissions;
    int hardLinks;
    char *owner;
    char *group;
    int size;
    char *month;
    char *day;
    char *timeOrYear;
    char *fileName;
    char *symlinkTarget;
} DiredEntry;

typedef struct {
    char *filepath;
    DiredEntry *entries;
    int count;
} DiredFileHandler;

DiredFileHandler* createHandler(const char *filepath) {
    DiredFileHandler *handler = malloc(sizeof(DiredFileHandler));
    handler->filepath = strdup(filepath);
    handler->entries = NULL;
    handler->count = 0;
    return handler;
}

void decodeAndRead(DiredFileHandler *handler) {
    FILE *file = fopen(handler->filepath, "r");
    if (!file) return;

    char line[1024];
    char *currentDir = NULL;
    while (fgets(line, sizeof(line), file)) {
        char *trimmed = strtok(line, "\n");
        if (!trimmed) continue;

        if (trimmed[strlen(trimmed) - 1] == ':') {
            free(currentDir);
            currentDir = strdup(trimmed);
            currentDir[strlen(currentDir) - 1] = '\0';
        } else if (strncmp(trimmed, "total", 5) != 0) {
            handler->entries = realloc(handler->entries, (handler->count + 1) * sizeof(DiredEntry));
            DiredEntry *entry = &handler->entries[handler->count++];

            entry->directory = strdup(currentDir);
            sscanf(trimmed, "%c%9s %d %s %s %d %s %s %s", &entry->fileType, entry->permissions = malloc(10),
                   &entry->hardLinks, entry->owner = malloc(32), entry->group = malloc(32),
                   &entry->size, entry->month = malloc(4), entry->day = malloc(3), entry->timeOrYear = malloc(5));

            // Parse file name and symlink
            char *nameStart = strstr(trimmed, entry->timeOrYear) + strlen(entry->timeOrYear) + 1;
            char *arrow = strstr(nameStart, " -> ");
            if (arrow) {
                entry->fileName = strndup(nameStart, arrow - nameStart);
                entry->symlinkTarget = strdup(arrow + 4);
            } else {
                entry->fileName = strdup(nameStart);
                entry->symlinkTarget = NULL;
            }
        }
    }
    free(currentDir);
    fclose(file);
}

void printProperties(DiredFileHandler *handler) {
    for (int i = 0; i < handler->count; i++) {
        DiredEntry *entry = &handler->entries[i];
        printf("Directory: %s\nFile Type: %c\nPermissions: %s\nHard Links: %d\nOwner: %s\nGroup: %s\nSize: %d\nMonth: %s\nDay: %s\nTime/Year: %s\nFile Name: %s\nSymlink Target: %s\n\n",
               entry->directory, entry->fileType, entry->permissions, entry->hardLinks, entry->owner, entry->group,
               entry->size, entry->month, entry->day, entry->timeOrYear, entry->fileName, entry->symlinkTarget ? entry->symlinkTarget : "None");
    }
}

void write(DiredFileHandler *handler, const char *newFilepath) {
    FILE *file = fopen(newFilepath ? newFilepath : handler->filepath, "w");
    if (!file) return;

    char *currentDir = NULL;
    for (int i = 0; i < handler->count; i++) {
        DiredEntry *entry = &handler->entries[i];
        if (!currentDir || strcmp(entry->directory, currentDir) != 0) {
            free(currentDir);
            currentDir = strdup(entry->directory);
            fprintf(file, "%s:\n", currentDir);
            fprintf(file, "total 0\n");  // Placeholder
        }
        char *symlink = entry->symlinkTarget ? malloc(strlen(entry->symlinkTarget) + 5) : "";
        if (entry->symlinkTarget) sprintf(symlink, " -> %s", entry->symlinkTarget);
        fprintf(file, "%c%s %d %s %s %d %s %s %s %s%s\n",
                entry->fileType, entry->permissions, entry->hardLinks, entry->owner, entry->group,
                entry->size, entry->month, entry->day, entry->timeOrYear, entry->fileName, symlink);
        free(symlink);
    }
    free(currentDir);
    fclose(file);
}

void destroyHandler(DiredFileHandler *handler) {
    for (int i = 0; i < handler->count; i++) {
        free(handler->entries[i].directory);
        free(handler->entries[i].permissions);
        free(handler->entries[i].owner);
        free(handler->entries[i].group);
        free(handler->entries[i].month);
        free(handler->entries[i].day);
        free(handler->entries[i].timeOrYear);
        free(handler->entries[i].fileName);
        free(handler->entries[i].symlinkTarget);
    }
    free(handler->entries);
    free(handler->filepath);
    free(handler);
}

