// ===== task-149 .DOT [C++] =====
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <regex>

class DotFile {
private:
    std::string content;
    std::map<std::string, std::string> properties;

public:
    DotFile(const std::string& filename) {
        std::ifstream file(filename);
        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                content += line + "\n";
            }
            file.close();
            decode();
        }
    }

    void decode() {
        std::regex regex(R"((\w+)\s*=\s*(".*?"|[^;,\s\]]+))");
        std::sregex_iterator iter(content.begin(), content.end(), regex);
        std::sregex_iterator end;
        for (; iter != end; ++iter) {
            std::string key = iter->str(1);
            std::string value = iter->str(2);
            value.erase(std::remove(value.begin(), value.end(), '"'), value.end());
            properties[key] = value;
        }
    }

    std::map<std::string, std::string> read() {
        return properties;
    }

    void printProperties() {
        for (const auto& pair : properties) {
            std::cout << pair.first << ": " << pair.second << std::endl;
        }
    }

    void setProperty(const std::string& key, const std::string& value) {
        if (properties.find(key) == properties.end()) {
            content += "\n" + key + " = \"" + value + "\";";
        } else {
            std::regex replace_regex(key + R"(\s*=\s*(".*?"|[^;]+))");
            content = std::regex_replace(content, replace_regex, key + " = \"" + value + "\"");
        }
        properties[key] = value;
    }

    void write(const std::string& filename) {
        std::ofstream file(filename);
        if (file.is_open()) {
            file << content;
            file.close();
        }
    }
};
// ===== end task-149 .DOT =====

