// ===== task-253 .GDSCRIPT [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

typedef struct {
    char* filepath;
    char* content;
    size_t size;
    struct {
        char extension[4];
        char format_type[12];
        char encoding[7];
        char line_endings[8];
        char indentation[10];
        char file_termination[16];
        char character_set[16];
        char mime_type[11];
        char bom_presence[20];
        char detected_line_endings[25];
        char detected_indentation[25];
        char file_termination_detected[25];
    } properties;
} GDScriptHandler;

void init_properties(GDScriptHandler* handler) {
    strcpy(handler->properties.extension, ".gd");
    strcpy(handler->properties.format_type, "Plain text");
    strcpy(handler->properties.encoding, "UTF-8");
    strcpy(handler->properties.line_endings, "LF (\\n)");
    strcpy(handler->properties.indentation, "Tabs (\\t)");
    strcpy(handler->properties.file_termination, "Single newline");
    strcpy(handler->properties.character_set, "Unicode (UTF-8)");
    strcpy(handler->properties.mime_type, "text/plain");
}

int read_and_decode(GDScriptHandler* handler) {
    FILE* file = fopen(handler->filepath, "rb");
    if (!file) {
        perror("Error opening file");
        return 0;
    }

    fseek(file, 0, SEEK_END);
    handler->size = ftell(file);
    fseek(file, 0, SEEK_SET);

    handler->content = malloc(handler->size + 1);
    fread(handler->content, 1, handler->size, file);
    handler->content[handler->size] = '\0';
    fclose(file);

    // Simple UTF-8 decode (assume valid); detect BOM
    if (handler->size >= 3 && handler->content[0] == 0xEF && handler->content[1] == 0xBB && handler->content[2] == 0xBF) {
        strcpy(handler->properties.bom_presence, "Yes (Non-standard)");
        // Shift content past BOM
        memmove(handler->content, handler->content + 3, handler->size - 3);
        handler->size -= 3;
        handler->content[handler->size] = '\0';
    } else {
        strcpy(handler->properties.bom_presence, "No - Standard");
    }

    detect_properties(handler);
    print_properties(handler);

    return 1;
}

void detect_properties(GDScriptHandler* handler) {
    // Detect line endings
    if (strstr(handler->content, "\r\n")) {
        strcpy(handler->properties.detected_line_endings, "CRLF (\\r\\n) - Non-standard");
    } else {
        strcpy(handler->properties.detected_line_endings, "LF (\\n) - Standard");
    }

    // Detect indentation (simple: find first indented line)
    char* indent_start = strstr(handler->content, "\n ");
    if (!indent_start) indent_start = strstr(handler->content, "\n\t");
    if (indent_start && *(indent_start + 2) == '\t') {
        strcpy(handler->properties.detected_indentation, "Tabs (\\t) - Standard");
    } else if (indent_start) {
        strcpy(handler->properties.detected_indentation, "Spaces - Non-standard");
    } else {
        strcpy(handler->properties.detected_indentation, "None detected");
    }

    if (handler->content[handler->size - 1] != '\n') {
        strcpy(handler->properties.file_termination_detected, "Non-standard");
    } else {
        strcpy(handler->properties.file_termination_detected, "Single newline - Standard");
    }
}

void print_properties(GDScriptHandler* handler) {
    printf("GDScript File Properties:\n");
    printf("EXTENSION: %s\n", handler->properties.extension);
    printf("FORMAT TYPE: %s\n", handler->properties.format_type);
    printf("ENCODING: %s\n", handler->properties.encoding);
    printf("LINE ENDINGS: %s\n", handler->properties.line_endings);
    printf("INDENTATION: %s\n", handler->properties.indentation);
    printf("FILE TERMINATION: %s\n", handler->properties.file_termination);
    printf("CHARACTER SET: %s\n", handler->properties.character_set);
    printf("MIME TYPE: %s\n", handler->properties.mime_type);
    printf("BOM PRESENCE: %s\n", handler->properties.bom_presence);
    printf("DETECTED LINE ENDINGS: %s\n", handler->properties.detected_line_endings);
    printf("DETECTED INDENTATION: %s\n", handler->properties.detected_indentation);
    printf("FILE TERMINATION DETECTED: %s\n", handler->properties.file_termination_detected);
    struct stat st;
    stat(handler->filepath, &st);
    printf("FILE SIZE: %ld bytes\n", (long)st.st_size);
    printf("\nRAW CONTENT PREVIEW:\n");
    handler->content[500] = '\0'; // Truncate for preview
    printf("%s...\n", handler->content);
}

void write_file(GDScriptHandler* handler, char* output_path) {
    // Normalize: remove CRLF, ensure LF end
    char* normalized = malloc(handler->size + 1);
    char* src = handler->content;
    char* dst = normalized;
    while (*src) {
        if (src[0] == '\r' && src[1] == '\n') {
            *dst++ = '\n';
            src += 2;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';

    if (normalized[handler->size - 1] != '\n') {
        strcat(normalized, "\n");
    }

    FILE* out = fopen(output_path ? output_path : handler->filepath, "wb");
    if (out) {
        fwrite(normalized, 1, strlen(normalized), out);
        fclose(out);
        printf("File written successfully to %s\n", output_path ? output_path : handler->filepath);
    } else {
        perror("Error writing file");
    }

    free(normalized);
}

void free_handler(GDScriptHandler* handler) {
    free(handler->content);
    free(handler->filepath);
    free(handler);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file.gd>\n", argv[0]);
        return 1;
    }

    GDScriptHandler* handler = malloc(sizeof(GDScriptHandler));
    handler->filepath = strdup(argv[1]);
    init_properties(handler);

    if (read_and_decode(handler)) {
        write_file(handler, NULL); // Write back to same file
    }

    free_handler(handler);
    return 0;
}
// ===== end task-253 .GDSCRIPT =====

// ===== task-254 .GDT [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

typedef struct {
    xmlDocPtr doc;
} GDTParser;

static void print_attr(xmlNodePtr node, const char* attr_name, const char* label) {
    xmlChar* attr_val = xmlGetProp(node, (const xmlChar*)attr_name);
    printf("    %s: %s\n", label, attr_val ? (char*)attr_val : "N/A");
    if (attr_val) xmlFree(attr_val);
}

void print_properties(GDTParser* parser) {
    xmlNodePtr root = xmlDocGetRootElement(parser->doc);
    if (!root || xmlStrcmp(root->name, (const xmlChar*)"gretldata")) {
        fprintf(stderr, "Not a valid .GDT file\n");
        return;
    }

    printf("=== .GDT File Properties ===\n");
    printf("\nRoot Attributes:\n");
    print_attr(root, "version", "- version");
    print_attr(root, "name", "- name");
    print_attr(root, "frequency", "- frequency");
    print_attr(root, "n", "- n");
    print_attr(root, "startobs", "- startobs");
    print_attr(root, "endobs", "- endobs");
    print_attr(root, "type", "- type");
    print_attr(root, "binary", "- binary");
    print_attr(root, "rseed", "- rseed");
    print_attr(root, "mapfile", "- mapfile");
    print_attr(root, "mpi-transfer", "- mpi-transfer");

    xmlNodePtr desc = NULL;
    for (xmlNodePtr child = root->children; child; child = child->next) {
        if (xmlStrcmp(child->name, (const xmlChar*)"description") == 0) {
            desc = child;
            break;
        }
    }
    if (desc) {
        xmlChar* text = xmlNodeGetContent(desc);
        printf("\nDescription:\n");
        printf("- Text: %s\n", text ? (char*)text : "N/A");
        print_attr(desc, "source", "- Source");
        if (text) xmlFree(text);
    }

    xmlNodePtr vars = NULL;
    for (xmlNodePtr child = root->children; child; child = child->next) {
        if (xmlStrcmp(child->name, (const xmlChar*)"variables") == 0) {
            vars = child;
            break;
        }
    }
    if (vars) {
        print_attr(vars, "count", "\nVariables (count:");
        printf("):\n");
        for (xmlNodePtr v = vars->children; v; v = v->next) {
            if (xmlStrcmp(v->name, (const xmlChar*)"variable") == 0) {
                xmlChar* name = xmlNodeGetContent(v);
                printf("  - Name: %s\n", name ? (char*)name : "N/A");
                print_attr(v, "label", "    Label");
                print_attr(v, "displayname", "    Displayname");
                print_attr(v, "parent", "    Parent");
                print_attr(v, "transform", "    Transform");
                print_attr(v, "lag", "    Lag");
                print_attr(v, "compact-method", "    Compact-method");
                print_attr(v, "discrete", "    Discrete");
                print_attr(v, "coded", "    Coded");
                print_attr(v, "role", "    Role");
                print_attr(v, "value", "    Value");
                printf("\n");
                if (name) xmlFree(name);
            }
        }
    }

    xmlNodePtr obs_elem = NULL;
    for (xmlNodePtr child = root->children; child; child = child->next) {
        if (xmlStrcmp(child->name, (const xmlChar*)"observations") == 0) {
            obs_elem = child;
            break;
        }
    }
    if (obs_elem) {
        print_attr(obs_elem, "count", "\nObservations (count:");
        printf("):\n");
        print_attr(obs_elem, "missval", "- Missval");
        print_attr(obs_elem, "labels", "- Labels");
        print_attr(obs_elem, "panel-info", "- Panel-info ref");
        for (xmlNodePtr o = obs_elem->children; o; o = o->next) {
            if (xmlStrcmp(o->name, (const xmlChar*)"obs") == 0) {
                xmlChar* values = xmlNodeGetContent(o);
                printf("  - Values: %s\n", values ? (char*)values : "N/A");
                print_attr(o, "label", "    Label");
                print_attr(o, "unit", "    Unit");
                print_attr(o, "period", "    Period");
                print_attr(o, "id", "    ID");
                printf("\n");
                if (values) xmlFree(values);
            }
        }
    }

    xmlNodePtr str_tables = NULL;
    for (xmlNodePtr child = root->children; child; child = child->next) {
        if (xmlStrcmp(child->name, (const xmlChar*)"string-tables") == 0) {
            str_tables = child;
            break;
        }
    }
    if (str_tables) {
        print_attr(str_tables, "count", "\nString Tables (count:");
        printf("):\n");
        for (xmlNodePtr s = str_tables->children; s; s = s->next) {
            if (xmlStrcmp(s->name, (const xmlChar*)"valstrings") == 0) {
                print_attr(s, "owner", "  - Owner");
                print_attr(s, "count", "    Count");
                xmlChar* strings = xmlNodeGetContent(s);
                printf("    Strings: %s\n", strings ? (char*)strings : "N/A");
                printf("\n");
                if (strings) xmlFree(strings);
            }
        }
    }

    xmlNodePtr panel = NULL;
    for (xmlNodePtr child = root->children; child; child = child->next) {
        if (xmlStrcmp(child->name, (const xmlChar*)"panel-info") == 0) {
            panel = child;
            break;
        }
    }
    if (panel) {
        printf("\nPanel Info:\n");
        print_attr(panel, "group-names", "- Group-names");
        print_attr(panel, "time-frequency", "- Time-frequency");
        print_attr(panel, "time-start", "- Time-start");
        print_attr(panel, "skip-padding", "- Skip-padding");
    }
}

void load(GDTParser* parser, const char* filename) {
    parser->doc = xmlReadFile(filename, NULL, 0);
    if (!parser->doc) {
        fprintf(stderr, "Failed to parse %s\n", filename);
        return;
    }
    print_properties(parser);
}

void write(GDTParser* parser, const char* filename) {
    if (!parser->doc) return;
    int success = xmlSaveFormatFileEnc(filename, parser->doc, "UTF-8", 1);
    if (success != -1) {
        printf("Written to %s\n", filename);
    } else {
        fprintf(stderr, "Write failed\n");
    }
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file.gdt>\n", argv[0]);
        return 1;
    }
    GDTParser parser = {0};
    load(&parser, argv[1]);
    // Example modification: xmlSetProp(xmlDocGetRootElement(parser.doc), (xmlChar*)"name", (xmlChar*)"Modified");
    // write(&parser, "modified.gdt");
    xmlFreeDoc(parser.doc);
    xmlCleanupParser();
    return 0;
}
