// ===== task-260 .GM9 [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *filename;
    char *properties[6][2];  // [name][desc]
    char *found_values[6];
} GM9Decoder;

void init_decoder(GM9Decoder *decoder, const char *filename) {
    decoder->filename = strdup(filename);
    // Initialize properties
    strcpy(decoder->properties[0][0], "CURRDIR");
    strcpy(decoder->properties[0][1], "Path to the directory containing the script file (no trailing forward slash).");
    strcpy(decoder->properties[1][0], "GM9OUT");
    strcpy(decoder->properties[1][1], "GodMode9's output directory path for dumps and logs.");
    strcpy(decoder->properties[2][0], "EMUBASE");
    strcpy(decoder->properties[2][1], "Base sector number of the current EmuNAND partition (integer value, or empty if no EmuNAND).");
    strcpy(decoder->properties[3][0], "SDSIZE");
    strcpy(decoder->properties[3][1], "Total size of the SD card, formatted with units (bytes if <1 KiB, KiB/MiB/GiB otherwise, rounded down to nearest tenth).");
    strcpy(decoder->properties[4][0], "SDFREE");
    strcpy(decoder->properties[4][1], "Free space on the SD card, formatted like SDSIZE (never exceeds SDSIZE).");
    strcpy(decoder->properties[5][0], "NANDSIZE");
    strcpy(decoder->properties[5][1], "Total size of SysNAND (including all partitions and bonus drive), formatted like SDSIZE.");
    for (int i = 0; i < 6; i++) {
        decoder->found_values[i] = NULL;
    }
}

void read_gm9(GM9Decoder *decoder) {
    FILE *file = fopen(decoder->filename, "r");
    if (!file) {
        printf("Error: %s not found.\n", decoder->filename);
        return;
    }
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char *trimmed = line;
        while (*trimmed == ' ' || *trimmed == '\t') trimmed++;
        if (strncmp(trimmed, "set ", 4) == 0) {
            char *second = strtok(trimmed + 4, " \t");
            if (second) {
                char *value = strtok(NULL, "\n");
                if (value) {
                    value += strspn(value, " \t");  // Skip spaces
                    for (int i = 0; i < 6; i++) {
                        if (strcmp(second, decoder->properties[i][0]) == 0) {
                            decoder->found_values[i] = strdup(value);
                            break;
                        }
                    }
                }
            }
        }
    }
    fclose(file);
    print_properties(decoder);
}

void print_properties(GM9Decoder *decoder) {
    printf("File System Properties:\n");
    for (int i = 0; i < 6; i++) {
        char *value = decoder->found_values[i] ? decoder->found_values[i] : "Not set in script (runtime value)";
        printf("%s: %s\n", decoder->properties[i][0], value);
        printf("Description: %s\n\n", decoder->properties[i][1]);
    }
}

void write_gm9(GM9Decoder *decoder, const char *output_filename) {
    char *out_name = strdup(output_filename ? output_filename : decoder->filename);
    FILE *in_file = fopen(decoder->filename, "r");
    FILE *out_file = fopen(out_name, "w");
    if (!in_file || !out_file) {
        printf("Write error.\n");
        free(out_name);
        if (in_file) fclose(in_file);
        return;
    }
    char line[1024];
    int modified = 0;
    while (fgets(line, sizeof(line), in_file)) {
        char *trimmed = line;
        while (*trimmed == ' ' || *trimmed == '\t') trimmed++;
        if (strncmp(trimmed, "set ", 4) == 0) {
            char *second = strtok(trimmed + 4, " \t\n");
            if (second) {
                for (int i = 0; i < 6; i++) {
                    if (strcmp(second, decoder->properties[i][0]) == 0) {
                        char new_line[1024];
                        snprintf(new_line, sizeof(new_line), "set %s %s\n", second, decoder->found_values[i] ? decoder->found_values[i] : "default_value");
                        fputs(new_line, out_file);
                        modified = 1;
                        break;
                    }
                }
                continue;
            }
        }
        fputs(line, out_file);
    }
    if (!modified) {
        for (int i = 0; i < 6; i++) {
            fprintf(out_file, "set %s default_value  # Example\n", decoder->properties[i][0]);
        }
    }
    fclose(in_file);
    fclose(out_file);
    printf("Written to %s\n", out_name);
    free(out_name);
}

void free_decoder(GM9Decoder *decoder) {
    free(decoder->filename);
    for (int i = 0; i < 6; i++) {
        if (decoder->found_values[i]) free(decoder->found_values[i]);
    }
}

// Usage
int main() {
    GM9Decoder decoder;
    init_decoder(&decoder, "example.gm9");
    read_gm9(&decoder);
    write_gm9(&decoder, NULL);
    free_decoder(&decoder);
    return 0;
}
// ===== end task-260 .GM9 =====

// ===== task-261 .GMI [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>  // For regex, or implement simple matching

// Simple struct for properties (simplified, no full lists for brevity)
typedef struct {
    int total_lines;
    int text_lines;
    int link_lines;
    int heading_lines[3];  // Index 0: #, 1: ##, 2: ###
    int list_items;
    int quote_lines;
    int pre_blocks;
    int links_count;  // Count only, no list
    int pre_alt_count;
    int final_pre_mode;
    char encoding[8];
} GMIProperties;

typedef struct {
    char *filepath;
    char **lines;
    int line_count;
    GMIProperties props;
} GMIFile;

void read_gmi(GMIFile *gmi) {
    FILE *f = fopen(gmi->filepath, "r");
    if (!f) return;
    char *line = NULL;
    size_t len = 0;
    gmi->line_count = 0;
    while (getline(&line, &len, f) != -1) {
        gmi->lines = realloc(gmi->lines, (gmi->line_count + 1) * sizeof(char*));
        gmi->lines[gmi->line_count] = strdup(line);
        gmi->line_count++;
    }
    free(line);
    fclose(f);
    parse_properties(gmi);
    print_properties(&gmi->props);
}

void parse_properties(GMIFile *gmi) {
    memset(&gmi->props, 0, sizeof(GMIProperties));
    gmi->props.total_lines = gmi->line_count;
    strcpy(gmi->props.encoding, "UTF-8");
    int in_pre = 0;
    for (int i = 0; i < gmi->line_count; i++) {
        char *line = gmi->lines[i];
        char *trimmed = line;
        while (*trimmed == ' ' || *trimmed == '\t') trimmed++;
        if (!*trimmed || *trimmed == '\n') continue;
        char *stripped = line;
        while (*stripped == ' ' || *stripped == '\t') stripped++;
        if (strncmp(stripped, "```", 3) == 0) {
            in_pre = !in_pre;
            gmi->props.pre_blocks++;
            // Simple alt text count (no extraction)
            gmi->props.pre_alt_count++;
            continue;
        }
        if (in_pre) continue;
        if (strncmp(stripped, "=>", 2) == 0) {
            gmi->props.link_lines++;
            gmi->props.links_count++;  // Simplified
        } else if (stripped[0] == '#') {
            int hashes = 0;
            while (stripped[hashes] == '#') hashes++;
            if (hashes <= 3) gmi->props.heading_lines[hashes - 1]++;
        } else if (strncmp(stripped, "* ", 2) == 0) {
            gmi->props.list_items++;
        } else if (stripped[0] == '>') {
            gmi->props.quote_lines++;
        } else {
            gmi->props.text_lines++;
        }
    }
    gmi->props.final_pre_mode = in_pre;
}

void print_properties(GMIProperties *props) {
    printf("total_lines: %d\n", props->total_lines);
    printf("text_lines: %d\n", props->text_lines);
    printf("link_lines: %d\n", props->link_lines);
    printf("heading_lines: [%d, %d, %d]\n", props->heading_lines[0], props->heading_lines[1], props->heading_lines[2]);
    printf("list_items: %d\n", props->list_items);
    printf("quote_lines: %d\n", props->quote_lines);
    printf("pre_blocks: %d\n", props->pre_blocks);
    printf("links_count: %d\n", props->links_count);
    printf("pre_alt_count: %d\n", props->pre_alt_count);
    printf("final_pre_mode: %d\n", props->final_pre_mode);
    printf("encoding: %s\n", props->encoding);
}

void write_gmi(GMIFile *gmi, char *output_path) {
    FILE *f = fopen(output_path, "w");
    if (!f) return;
    for (int i = 0; i < gmi->line_count; i++) {
        fprintf(f, "%s\r\n", gmi->lines[i]);  // Canonical CRLF
    }
    fclose(f);
}

void free_gmi(GMIFile *gmi) {
    for (int i = 0; i < gmi->line_count; i++) free(gmi->lines[i]);
    free(gmi->lines);
}

