// ===== task-283 .HDF5 [C++] =====
#include <iostream>
#include <fstream>
#include <vector>
#include <cstdint>
#include <cstring>
#include <map>
#include <string>

class HDF5Parser {
private:
    std::string filepath;
    std::map<std::string, uint64_t> properties; // Using uint64_t for simplicity; adjust for strings/large ints

public:
    HDF5Parser(const std::string& fp) : filepath(fp) {}

    void readAndDecode() {
        std::ifstream file(filepath, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Cannot open file");
        }
        std::vector<uint8_t> data(1024);
        file.read(reinterpret_cast<char*>(data.data()), 1024);
        uint8_t sig[8];
        std::memcpy(sig, data.data(), 8);
        if (sig[0] != 137 || sig[1] != 72 || sig[2] != 68 || sig[3] != 70 ||
            sig[4] != 13 || sig[5] != 10 || sig[6] != 26 || sig[7] != 10) {
            throw std::runtime_error("Invalid HDF5 signature");
        }
        uint8_t version = data[8];
        properties["Superblock Version"] = version;
        size_t pos = 9;
        if (version == 0 || version == 1) {
            properties["Free Space Version"] = data[pos++];
            properties["Root Group Version"] = data[pos++];
            pos++; // Reserved
            properties["Shared Header Message Version"] = data[pos++];
            uint8_t offsetSize = data[pos++];
            properties["Size of Offsets"] = offsetSize;
            uint8_t lengthSize = data[pos++];
            properties["Size of Lengths"] = lengthSize;
            pos++; // Reserved
            uint16_t leafK; std::memcpy(&leafK, &data[pos], 2); properties["Group Leaf Node K"] = leafK; pos += 2;
            uint16_t internalK; std::memcpy(&internalK, &data[pos], 2); properties["Group Internal Node K"] = internalK; pos += 2;
            if (version == 0) {
                pos += 4; // Reserved
            } else {
                uint32_t flags; std::memcpy(&flags, &data[pos], 4); properties["File Consistency Flags"] = flags; pos += 4;
            }
            properties["Base Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
            properties["Free Space Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
            properties["End of File Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
            properties["Driver Info Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
        } else if (version == 2 || version == 3) {
            uint8_t offsetSize = data[pos++];
            properties["Size of Offsets"] = offsetSize;
            uint8_t lengthSize = data[pos++];
            properties["Size of Lengths"] = lengthSize;
            properties["File Consistency Flags"] = data[pos++];
            properties["Base Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
            properties["Superblock Extension Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
            properties["End of File Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
            properties["Root Group Object Header Address"] = getUInt64(&data[pos], offsetSize); pos += offsetSize;
            uint32_t checksum; std::memcpy(&checksum, &data[pos], 4); properties["Superblock Checksum"] = checksum;
        } else {
            throw std::runtime_error("Unsupported superblock version");
        }
    }

    uint64_t getUInt64(const uint8_t* ptr, size_t size) {
        uint64_t val = 0;
        for (size_t i = 0; i < size; ++i) {
            val |= static_cast<uint64_t>(ptr[i]) << (i * 8);
        }
        return val;
    }

    void printProperties() {
        for (const auto& p : properties) {
            std::cout << p.first << ": " << p.second << std::endl;
        }
    }

    void writeMinimal(const std::string& outputPath) {
        std::ofstream file(outputPath, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Cannot create file");
        }
        uint8_t sig[8] = {137, 72, 68, 70, 13, 10, 26, 10};
        file.write(reinterpret_cast<char*>(sig), 8);
        file.put(3); // Version
        file.put(8); // Offset size
        file.put(8); // Length size
        file.put(0); // Flags
        setUInt64(file, 0, 8); // Base addr
        setUInt64(file, 0xFFFFFFFFFFFFFFFFULL, 8); // Ext addr
        setUInt64(file, 1024, 8); // EOF
        setUInt64(file, 96, 8); // Root addr
        uint32_t checksum = 0;
        file.write(reinterpret_cast<char*>(&checksum), 4);
    }

    void setUInt64(std::ofstream& file, uint64_t val, size_t size) {
        for (size_t i = 0; i < size; ++i) {
            file.put(static_cast<uint8_t>(val >> (i * 8)));
        }
    }
};
// ===== end task-283 .HDF5 =====

// ===== task-284 .HDI [C++] =====
#include <iostream>
#include <fstream>
#include <vector>
#include <cstdint>
#include <cstring>

class HDIFile {
private:
    std::string filepath;
    uint32_t reserved = 0;
    uint32_t fddType = 0;
    uint32_t headerSize = 0;
    uint32_t dataSize = 0;
    uint32_t bytesPerSector = 0;
    uint32_t sectors = 0;
    uint32_t heads = 0;
    uint32_t cylinders = 0;
    std::vector<uint8_t> comment;

public:
    HDIFile(const std::string& fp = "") : filepath(fp) {
        if (!fp.empty()) {
            read(fp);
        }
    }

    void read(const std::string& fp) {
        filepath = fp;
        std::ifstream file(fp, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Cannot open file");
        }
        uint32_t header[8];
        file.read(reinterpret_cast<char*>(header), 32);
        if (file.gcount() < 32) {
            throw std::runtime_error("Invalid HDI file: Header too short");
        }
        reserved = header[0];
        fddType = header[1];
        headerSize = header[2];
        dataSize = header[3];
        bytesPerSector = header[4];
        sectors = header[5];
        heads = header[6];
        cylinders = header[7];
        if (reserved != 0) {
            std::cout << "Warning: Reserved field is not zero" << std::endl;
        }
        if (headerSize > 32) {
            comment.resize(headerSize - 32);
            file.read(reinterpret_cast<char*>(comment.data()), headerSize - 32);
        }
    }

    void printProperties() const {
        std::cout << "Reserved: " << reserved << std::endl;
        std::cout << "FDDType: " << fddType << std::endl;
        std::cout << "HeaderSize: " << headerSize << std::endl;
        std::cout << "DataSize: " << dataSize << std::endl;
        std::cout << "BytesPerSector: " << bytesPerSector << std::endl;
        std::cout << "Sectors: " << sectors << std::endl;
        std::cout << "Heads: " << heads << std::endl;
        std::cout << "Cylinders: " << cylinders << std::endl;
        std::string commentStr(comment.begin(), comment.end());
        std::cout << "Comment: " << (commentStr.empty() ? "None" : commentStr) << std::endl;
    }

    void write(const std::string& outputPath = "") const {
        std::string out = outputPath.empty() ? (filepath.empty() ? "output.hdi" : filepath) : outputPath;
        std::ofstream file(out, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Cannot write file");
        }
        uint32_t header[8] = {reserved, fddType, headerSize, dataSize, bytesPerSector, sectors, heads, cylinders};
        file.write(reinterpret_cast<const char*>(header), 32);
        if (!comment.empty()) {
            file.write(reinterpret_cast<const char*>(comment.data()), comment.size());
        }
        // Note: Data segment not written; append if needed
    }
};
// ===== end task-284 .HDI =====

// ===== task-282 .HAR [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/stat.h>

typedef struct {
    char *filename;
    uint8_t *buffer;
    size_t file_size;
    struct DD *dds;
    int num_dds;
} HDF4Handler;

typedef struct {
    uint16_t tag;
    uint16_t ref;
    int32_t offset;
    int32_t length;
} DD;

void parse_signature(HDF4Handler *h) {
    uint8_t sig[4];
    memcpy(sig, h->buffer, 4);
    uint8_t expected[4] = {0x0E, 0x03, 0x13, 0x01};
    int valid = (sig[0] == expected[0] && sig[1] == expected[1] && sig[2] == expected[2] && sig[3] == expected[3]);
    printf("Signature: %s (0x%02X 0x%02X 0x%02X 0x%02X)\n", valid ? "Valid HDF4" : "Invalid",
           sig[0], sig[1], sig[2], sig[3]);
}

void parse_version(HDF4Handler *h) {
    for (int i = 0; i < h->num_dds; i++) {
        if (h->dds[i].tag == 30) {  // 0x001E
            uint8_t *data = h->buffer + h->dds[i].offset;
            uint32_t ver_int = *(uint32_t *)data;  // Big-endian assumed
            char ver_str[32];
            strncpy(ver_str, (char *)(data + 4), h->dds[i].length - 4);
            ver_str[h->dds[i].length - 4] = '\0';
            printf("Version: %u - %s\n", ver_int, ver_str);
            return;
        }
    }
    printf("Version not found\n");
}

DD *parse_dd_blocks(HDF4Handler *h, int *num) {
    DD *dds = malloc(1024 * sizeof(DD));  // Arbitrary max
    int count = 0;
    size_t offset = 4;
    while (offset < h->file_size) {
        if (offset + 6 > h->file_size) break;
        uint16_t block_size = *(uint16_t *)(h->buffer + offset);
        uint32_t next_offset = *(uint32_t *)(h->buffer + offset + 2);
        offset += 6;
        for (int i = 0; i < block_size; i++) {
            if (offset + 12 > h->file_size) break;
            uint16_t tag = *(uint16_t *)(h->buffer + offset);
            uint16_t ref = *(uint16_t *)(h->buffer + offset + 2);
            int32_t data_offset = *(int32_t *)(h->buffer + offset + 4);
            int32_t length = *(int32_t *)(h->buffer + offset + 8);
            if (tag != 0) {
                dds[count].tag = tag;
                dds[count].ref = ref;
                dds[count].offset = data_offset;
                dds[count].length = length;
                count++;
            }
            offset += 12;
        }
        offset = next_offset;
        if (next_offset == 0) break;
    }
    *num = count;
    return dds;
}

void print_properties(HDF4Handler *h) {
    printf("File Size: %zu bytes\n", h->file_size);
    printf("Data Descriptors (%d total):\n", h->num_dds);
    for (int i = 0; i < h->num_dds; i++) {
        printf("  DD%d: Tag 0x%04X, Ref %d, Offset %d, Length %d\n",
               i, h->dds[i].tag, h->dds[i].ref, h->dds[i].offset, h->dds[i].length);
    }
}

char *parse_vgroup(HDF4Handler *h, uint16_t ref) {
    for (int i = 0; i < h->num_dds; i++) {
        if (h->dds[i].ref == ref && h->dds[i].tag == 1973) {  // 0x07B5
            char *str = malloc(100);
            snprintf(str, 100, "Offset %d, Length %d (hierarchy refs omitted)", h->dds[i].offset, h->dds[i].length);
            return str;
        }
    }
    return strdup("Vgroup not found");
}

void hdf4_read(HDF4Handler *h) {
    FILE *f = fopen(h->filename, "rb");
    if (!f) {
        printf("File not found.\n");
        return;
    }
    fseek(f, 0, SEEK_END);
    h->file_size = ftell(f);
    fseek(f, 0, SEEK_SET);
    h->buffer = malloc(h->file_size);
    fread(h->buffer, 1, h->file_size, f);
    fclose(f);
    parse_signature(h);
    parse_version(h);
    h->dds = parse_dd_blocks(h, &h->num_dds);
    print_properties(h);
    if (h->num_dds > 0) {
        char *vg = parse_vgroup(h, 1);
        printf("Example Vgroup (ref 1): %s\n", vg);
        free(vg);
    }
}

void hdf4_write(HDF4Handler *h, char *output_filename) {
    FILE *f = fopen(output_filename, "wb");
    if (!f) return;
    // Signature
    fwrite((uint8_t[]){0x0E, 0x03, 0x13, 0x01}, 1, 4, f);
    // DD block header
    uint16_t block_size = 2;
    uint32_t next = 0;
    fwrite(&block_size, 2, 1, f);
    fwrite(&next, 4, 1, f);
    // Version DD
    uint16_t tag1 = 30, ref1 = 1;
    int32_t off1 = 36, len1 = 8;
    fwrite(&tag1, 2, 1, f); fwrite(&ref1, 2, 1, f);
    fwrite(&off1, 4, 1, f); fwrite(&len1, 4, 1, f);
    // Vgroup DD
    uint16_t tag2 = 1973, ref2 = 2;
    int32_t off2 = 44, len2 = 4;
    fwrite(&tag2, 2, 1, f); fwrite(&ref2, 2, 1, f);
    fwrite(&off2, 4, 1, f); fwrite(&len2, 4, 1, f);
    // Dummy version
    uint32_t ver_int = 1;
    fwrite(&ver_int, 4, 1, f);
    fwrite("HDF4.0", 1, 6, f);
    // Dummy Vgroup
    uint32_t zero = 0;
    fwrite(&zero, 4, 1, f);
    fclose(f);
    printf("Simple .HDF written to %s\n", output_filename);
}

int main() {
    HDF4Handler h = { .filename = "sample.hdf" };
    hdf4_read(&h);
    // Free resources...
    free(h.buffer);
    free(h.dds);
    hdf4_write(&h, "simple.hdf");
    return 0;
}
