#include <iostream>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <string>
#include <ctime>
#include <fstream>

class HtmFileHandler {
private:
    std::string filepath;
    struct stat stats;

public:
    HtmFileHandler(const std::string& fp) : filepath(fp) {
        if (filepath.substr(filepath.find_last_of(".") + 1) != "htm") {
            throw std::invalid_argument("File must have .htm extension");
        }
        if (stat(filepath.c_str(), &stats) != 0) {
            throw std::runtime_error("Failed to get file stats");
        }
    }

    void readAndPrintProperties() {
        std::cout << "File Name: " << filepath.substr(filepath.find_last_of("/\\") + 1) << std::endl;
        std::cout << "File Size: " << stats.st_size << " bytes" << std::endl;
        std::cout << "MIME Type: text/html (inferred for .htm)" << std::endl;
        std::cout << "Last Modified Time: " << std::ctime(&stats.st_mtime);
        std::cout << "Creation Time: " << std::ctime(&stats.st_ctime);  // On Unix, ctime is status change; no standard birth time
        std::cout << "Last Access Time: " << std::ctime(&stats.st_atime);
        std::cout << "Permissions: " << std::oct << (stats.st_mode & 0777) << std::dec << std::endl;
        std::cout << "Owner User ID: " << stats.st_uid << std::endl;
        std::cout << "Owner Group ID: " << stats.st_gid << std::endl;
        std::cout << "Inode Number: " << stats.st_ino << std::endl;
        std::cout << "Device ID: " << stats.st_dev << std::endl;
        std::cout << "Number of Hard Links: " << stats.st_nlink << std::endl;
    }

    void writeSampleHtm(const std::string& content = "<html><body>Hello World</body></html>") {
        std::ofstream file(filepath);
        if (file.is_open()) {
            file << content;
            file.close();
            std::cout << "Written sample content to " << filepath << std::endl;
        } else {
            throw std::runtime_error("Failed to write file");
        }
    }
};

