#include <iostream>
#include <string>
#include <map>
#include <zip.h>
#include <libxml/parser.h>

class KraHandler {
private:
    std::string filepath;
    zip_t* zip;
    std::map<std::string, std::string> properties;

public:
    KraHandler(const std::string& fp) : filepath(fp), zip(nullptr) {}

    ~KraHandler() { close(); }

    void open() {
        int err = 0;
        zip = zip_open(filepath.c_str(), 0, &err);
        if (!zip) std::cerr << "Failed to open ZIP" << std::endl;
    }

    void decodeRead() {
        if (!zip) open();
        // Read maindoc.xml
        zip_file_t* file = zip_fopen(zip, "maindoc.xml", 0);
        zip_stat_t stat;
        zip_stat(zip, "maindoc.xml", 0, &stat);
        char* buf = new char[stat.size + 1];
        zip_fread(file, buf, stat.size);
        buf[stat.size] = '\0';
        xmlDocPtr doc = xmlParseMemory(buf, stat.size);
        xmlNodePtr root = xmlDocGetRootElement(doc);
        xmlNodePtr image = nullptr;
        for (xmlNodePtr node = root->children; node; node = node->next) {
            if (xmlStrcmp(node->name, (const xmlChar*)"IMAGE") == 0) {
                image = node;
                break;
            }
        }
        if (image) {
            properties["Document Width"] = (char*)xmlGetProp(image, (const xmlChar*)"width");
            properties["Document Height"] = (char*)xmlGetProp(image, (const xmlChar*)"height");
            properties["Color Space Name"] = (char*)xmlGetProp(image, (const xmlChar*)"colorspacename");
            int layerCount = 0;
            for (xmlNodePtr node = root; node; node = node->next) if (xmlStrcmp(node->name, (const xmlChar*)"layer") == 0) layerCount++;
            properties["Number of Layers"] = std::to_string(layerCount);
        }
        xmlFreeDoc(doc);
        zip_fclose(file);
        delete[] buf;
        // Find first layer file
        const char* layerName = nullptr;
        int num = zip_get_num_entries(zip, 0);
        for (int i = 0; i < num; i++) {
            const char* name = zip_get_name(zip, i, 0);
            if (std::string(name).find("/layers/layer") != std::string::npos && std::string(name).find(".") == std::string::npos) {
                layerName = name;
                break;
            }
        }
        if (layerName) {
            file = zip_fopen(zip, layerName, 0);
            zip_stat(zip, layerName, 0, &stat);
            buf = new char[stat.size + 1];
            zip_fread(file, buf, stat.size);
            buf[stat.size] = '\0';
            std::string data(buf);
            size_t pos = 0;
            std::string line = data.substr(0, data.find('\n'));
            properties["Version"] = line.substr(line.find(' ') + 1);
            pos = data.find('\n') + 1;
            line = data.substr(pos, data.find('\n', pos) - pos);
            properties["Tile Width"] = line.substr(line.find(' ') + 1);
            pos = data.find('\n', pos) + 1;
            line = data.substr(pos, data.find('\n', pos) - pos);
            properties["Tile Height"] = line.substr(line.find(' ') + 1);
            pos = data.find('\n', pos) + 1;
            line = data.substr(pos, data.find('\n', pos) - pos);
            properties["Pixel Size"] = line.substr(line.find(' ') + 1);
            pos = data.find('\n', pos) + 1;
            line = data.substr(pos, data.find('\n', pos) - pos);
            size_t comma2 = line.find(',', line.find(',') + 1);
            size_t comma3 = line.find(',', comma2 + 1);
            properties["Compression Type"] = line.substr(comma2 + 1, comma3 - comma2 - 1);
            zip_fclose(file);
            delete[] buf;
        }
        properties["Bit Depth"] = std::to_string(std::stoi(properties["Pixel Size"]) * 8 / 4);
        properties["Has Animation"] = (zip_name_locate(zip, "keyframes.xml", 0) >= 0) ? "Yes" : "No";
        properties["ICC Profile"] = (zip_name_locate(zip, ".icc", ZIP_FL_ENC_GUESS | ZIP_FL_NOCASE) >= 0) ? "Present" : "Absent";
        // Default pixel
        const char* defPixelName = nullptr;
        for (int i = 0; i < num; i++) {
            const char* name = zip_get_name(zip, i, 0);
            if (std::string(name).ends_with(".defaultpixel")) {
                defPixelName = name;
                break;
            }
        }
        if (defPixelName) {
            file = zip_fopen(zip, defPixelName, 0);
            zip_stat(zip, defPixelName, 0, &stat);
            buf = new char[stat.size];
            zip_fread(file, buf, stat.size);
            properties["Default Pixel"] = std::string(buf, stat.size);  // Binary, so string rep
            zip_fclose(file);
            delete[] buf;
        } else {
            properties["Default Pixel"] = "N/A";
        }
    }

    void printProperties() {
        for (const auto& p : properties) {
            std::cout << p.first << ": " << p.second << std::endl;
        }
    }

    void write(const std::string& newFilepath) {
        // Simple copy and modify maindoc.xml
        zip_t* newZip = zip_open(newFilepath.c_str(), ZIP_CREATE | ZIP_TRUNCATE, nullptr);
        int num = zip_get_num_entries(zip, 0);
        for (int i = 0; i < num; i++) {
            const char* name = zip_get_name(zip, i, 0);
            zip_file_t* file = zip_fopen_index(zip, i, 0);
            zip_stat_t stat;
            zip_stat_index(zip, i, 0, &stat);
            char* buf = new char[stat.size];
            zip_fread(file, buf, stat.size);
            zip_file_add(newZip, name, zip_buffer_create(buf, stat.size), ZIP_FL_OVERWRITE);
            zip_fclose(file);
            // Modify if maindoc.xml
            if (std::string(name) == "maindoc.xml") {
                xmlDocPtr doc = xmlParseMemory(buf, stat.size);
                xmlNodePtr image = nullptr;
                xmlNodePtr root = xmlDocGetRootElement(doc);
                for (xmlNodePtr node = root->children; node; node = node->next) {
                    if (xmlStrcmp(node->name, (const xmlChar*)"IMAGE") == 0) {
                        image = node;
                        break;
                    }
                }
                if (image) {
                    xmlChar* width = xmlGetProp(image, (const xmlChar*)"width");
                    int newWidth = std::stoi((char*)width) + 10;
                    xmlSetProp(image, (const xmlChar*)"width", (const xmlChar*)std::to_string(newWidth).c_str());
                    xmlFree(width);
                }
                xmlChar* xmlBuf;
                int size;
                xmlDocDumpMemory(doc, &xmlBuf, &size);
                zip_file_replace(newZip, zip_name_locate(newZip, name, 0), zip_buffer_create((char*)xmlBuf, size), 0);
                xmlFreeDoc(doc);
            }
            delete[] buf;
        }
        zip_close(newZip);
    }

    void close() {
        if (zip) zip_close(zip);
    }
};

int main() {
    KraHandler handler("example.kra");
    handler.open();
    handler.decodeRead();
    handler.printProperties();
    handler.write("modified.kra");
    return 0;
}
// ===== end task-344 .KRA =====

// ===== task-346 .KSH [C++] =====
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <sstream>

class KSHFile {
private:
    std::map<std::string, std::string> headerProps;
    std::vector<std::map<std::string, std::string>> bodyMeasures; // Each measure's props
    std::vector<std::string> bodyChartLinesPerMeasure; // Parallel vector for chart lines (simplified)
    std::vector<std::string> comments;
    std::vector<std::string> definitions;

public:
    KSHFile(const std::string& filepath = "") {
        if (!filepath.empty()) {
            read(filepath);
        }
    }

    void read(const std::string& filepath) {
        std::ifstream file(filepath, std::ios::in | std::ios::binary); // For BOM handling
        if (!file) {
            std::cerr << "Failed to open file." << std::endl;
            return;
        }
        // Skip BOM if present
        char bom[3];
        file.read(bom, 3);
        if (!(bom[0] == (char)0xEF && bom[1] == (char)0xBB && bom[2] == (char)0xBF)) {
            file.seekg(0);
        }
        std::string line;
        bool inBody = false;
        std::map<std::string, std::string> currentMeasure;
        std::vector<std::string> currentChartLines;
        int measureIndex = -1;
        while (std::getline(file, line)) {
            line.erase(std::remove(line.begin(), line.end(), '\r'), line.end()); // Trim CR
            if (line.empty()) continue;
            if (line.substr(0, 2) == "//") {
                comments.push_back(line);
                continue;
            }
            if (line == "--") {
                if (!currentMeasure.empty() || !currentChartLines.empty()) {
                    bodyMeasures.push_back(currentMeasure);
                    bodyChartLinesPerMeasure.push_back(currentChartLines);
                }
                currentMeasure.clear();
                currentChartLines.clear();
                inBody = true;
                measureIndex++;
                continue;
            }
            if (line.substr(0, 7) == "#define") {
                definitions.push_back(line);
                continue;
            }
            size_t eqPos = line.find('=');
            if (eqPos != std::string::npos) {
                std::string key = line.substr(0, eqPos);
                std::string value = line.substr(eqPos + 1);
                // Trim spaces
                key.erase(0, key.find_first_not_of(" \t"));
                key.erase(key.find_last_not_of(" \t") + 1);
                value.erase(0, value.find_first_not_of(" \t"));
                value.erase(value.find_last_not_of(" \t") + 1);
                if (inBody) {
                    currentMeasure[key] = value;
                } else {
                    headerProps[key] = value;
                }
            } else {
                if (inBody) {
                    currentChartLines.push_back(line);
                }
            }
        }
        if (!currentMeasure.empty() || !currentChartLines.empty()) {
            bodyMeasures.push_back(currentMeasure);
            bodyChartLinesPerMeasure.push_back(currentChartLines);
        }
    }

    void printProperties() {
        std::cout << "Header Properties:" << std::endl;
        for (const auto& pair : headerProps) {
            std::cout << pair.first << ": " << pair.second << std::endl;
        }
        std::cout << "\nBody Measures:" << std::endl;
        for (size_t i = 0; i < bodyMeasures.size(); ++i) {
            std::cout << "Measure " << (i + 1) << ":" << std::endl;
            for (const auto& pair : bodyMeasures[i]) {
                std::cout << "  " << pair.first << ": " << pair.second << std::endl;
            }
            std::cout << "  chart_lines:" << std::endl;
            for (const auto& cl : bodyChartLinesPerMeasure[i]) {
                std::cout << "    " << cl << std::endl;
            }
        }
        if (!definitions.empty()) {
            std::cout << "\nDefinitions:" << std::endl;
            for (const auto& def : definitions) {
                std::cout << def << std::endl;
            }
        }
        if (!comments.empty()) {
            std::cout << "\nComments:" << std::endl;
            for (const auto& comment : comments) {
                std::cout << comment << std::endl;
            }
        }
    }

    void write(const std::string& filepath) {
        std::ofstream file(filepath, std::ios::out | std::ios::binary);
        if (!file) {
            std::cerr << "Failed to write file." << std::endl;
            return;
        }
        // Write BOM
        file << (char)0xEF << (char)0xBB << (char)0xBF;
        // Header
        for (const auto& pair : headerProps) {
            file << pair.first << "=" << pair.second << "\n";
        }
        // Definitions
        for (const auto& def : definitions) {
            file << def << "\n";
        }
        // Body
        for (size_t i = 0; i < bodyMeasures.size(); ++i) {
            file << "--\n";
            for (const auto& pair : bodyMeasures[i]) {
                file << pair.first << "=" << pair.second << "\n";
            }
            for (const auto& cl : bodyChartLinesPerMeasure[i]) {
                file << cl << "\n";
            }
        }
        // Comments not written
    }
};

int main() {
    KSHFile ksh("example.ksh");
    ksh.printProperties();
    ksh.write("output.ksh");
    return 0;
}
// ===== end task-346 .KSH =====

// ===== task-347 .KT [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint8_t identifier[12];
    uint32_t vkFormat;
    uint32_t typeSize;
    uint32_t pixelWidth;
    uint32_t pixelHeight;
    uint32_t pixelDepth;
    uint32_t layerCount;
    uint32_t faceCount;
    uint32_t levelCount;
    uint32_t supercompressionScheme;
    uint32_t dfdByteOffset;
    uint32_t dfdByteLength;
    uint32_t kvdByteOffset;
    uint32_t kvdByteLength;
    uint64_t sgdByteOffset;
    uint64_t sgdByteLength;
    struct Level {
        uint64_t byteOffset;
        uint64_t byteLength;
        uint64_t uncompressedByteLength;
    } *levelIndex;
} KTFile;

void read_kt_file(const char *filename, KTFile *kt) {
    FILE *f = fopen(filename, "rb");
    if (!f) {
        perror("Error opening file");
        exit(1);
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    uint8_t *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    memcpy(kt->identifier, data, 12);

    memcpy(&kt->vkFormat, data + 12, 4);
    memcpy(&kt->typeSize, data + 16, 4);
    memcpy(&kt->pixelWidth, data + 20, 4);
    memcpy(&kt->pixelHeight, data + 24, 4);
    memcpy(&kt->pixelDepth, data + 28, 4);
    memcpy(&kt->layerCount, data + 32, 4);
    memcpy(&kt->faceCount, data + 36, 4);
    memcpy(&kt->levelCount, data + 40, 4);
    memcpy(&kt->supercompressionScheme, data + 44, 4);
    memcpy(&kt->dfdByteOffset, data + 48, 4);
    memcpy(&kt->dfdByteLength, data + 52, 4);
    memcpy(&kt->kvdByteOffset, data + 56, 4);
    memcpy(&kt->kvdByteLength, data + 60, 4);
    memcpy(&kt->sgdByteOffset, data + 64, 8);
    memcpy(&kt->sgdByteLength, data + 72, 8);

    kt->levelIndex = malloc(kt->levelCount * sizeof(struct Level));
    for (uint32_t i = 0; i < kt->levelCount; i++) {
        size_t base = 80 + i * 24;
        memcpy(&kt->levelIndex[i].byteOffset, data + base, 8);
        memcpy(&kt->levelIndex[i].byteLength, data + base + 8, 8);
        memcpy(&kt->levelIndex[i].uncompressedByteLength, data + base + 16, 8);
    }

    free(data);
}

void print_kt_properties(const KTFile *kt) {
    printf("KT File Properties:\n");
    printf("identifier: ");
    for (int i = 0; i < 12; i++) {
        printf("%u ", kt->identifier[i]);
    }
    printf("\n");
    printf("vkFormat: %u\n", kt->vkFormat);
    printf("typeSize: %u\n", kt->typeSize);
    printf("pixelWidth: %u\n", kt->pixelWidth);
    printf("pixelHeight: %u\n", kt->pixelHeight);
    printf("pixelDepth: %u\n", kt->pixelDepth);
    printf("layerCount: %u\n", kt->layerCount);
    printf("faceCount: %u\n", kt->faceCount);
    printf("levelCount: %u\n", kt->levelCount);
    printf("supercompressionScheme: %u\n", kt->supercompressionScheme);
    printf("dfdByteOffset: %u\n", kt->dfdByteOffset);
    printf("dfdByteLength: %u\n", kt->dfdByteLength);
    printf("kvdByteOffset: %u\n", kt->kvdByteOffset);
    printf("kvdByteLength: %u\n", kt->kvdByteLength);
    printf("sgdByteOffset: %lu\n", kt->sgdByteOffset);
    printf("sgdByteLength: %lu\n", kt->sgdByteLength);
    printf("levelIndex:\n");
    for (uint32_t i = 0; i < kt->levelCount; i++) {
        printf("  Level %u:\n", i);
        printf("    byteOffset: %lu\n", kt->levelIndex[i].byteOffset);
        printf("    byteLength: %lu\n", kt->levelIndex[i].byteLength);
        printf("    uncompressedByteLength: %lu\n", kt->levelIndex[i].uncompressedByteLength);
    }
}

void write_kt_file(const char *output_filename, const KTFile *kt) {
    size_t header_size = 80 + kt->levelCount * 24;
    uint8_t *header = malloc(header_size);

    memcpy(header, kt->identifier, 12);
    memcpy(header + 12, &kt->vkFormat, 4);
    memcpy(header + 16, &kt->typeSize, 4);
    memcpy(header + 20, &kt->pixelWidth, 4);
    memcpy(header + 24, &kt->pixelHeight, 4);
    memcpy(header + 28, &kt->pixelDepth, 4);
    memcpy(header + 32, &kt->layerCount, 4);
    memcpy(header + 36, &kt->faceCount, 4);
    memcpy(header + 40, &kt->levelCount, 4);
    memcpy(header + 44, &kt->supercompressionScheme, 4);
    memcpy(header + 48, &kt->dfdByteOffset, 4);
    memcpy(header + 52, &kt->dfdByteLength, 4);
    memcpy(header + 56, &kt->kvdByteOffset, 4);
    memcpy(header + 60, &kt->kvdByteLength, 4);
    memcpy(header + 64, &kt->sgdByteOffset, 8);
    memcpy(header + 72, &kt->sgdByteLength, 8);

    for (uint32_t i = 0; i < kt->levelCount; i++) {
        size_t base = 80 + i * 24;
        memcpy(header + base, &kt->levelIndex[i].byteOffset, 8);
        memcpy(header + base + 8, &kt->levelIndex[i].byteLength, 8);
        memcpy(header + base + 16, &kt->levelIndex[i].uncompressedByteLength, 8);
    }

    FILE *f = fopen(output_filename, "wb");
    if (!f) {
        perror("Error opening output file");
        exit(1);
    }
    fwrite(header, 1, header_size, f);
    fclose(f);
    free(header);
    printf("Written to %s\n", output_filename);
}

void free_kt(KTFile *kt) {
    free(kt->levelIndex);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s input.kt [output.kt]\n", argv[0]);
        return 1;
    }

    KTFile kt;
    read_kt_file(argv[1], &kt);
    print_kt_properties(&kt);

    if (argc > 2) {
        write_kt_file(argv[2], &kt);
    }

    free_kt(&kt);
    return 0;
}
