// ===== task-411 .MOP [C++] =====
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <string>
#include <iomanip>

class MopFile {
private:
    std::vector<std::string> keywords;
    std::string title;
    std::string comment;
    std::vector<std::map<std::string, double>> atoms; // Use double for all numeric, cast ints
    bool isCartesian;

    bool startsWith(const std::string& str, const std::string& prefix) {
        return str.compare(0, prefix.length(), prefix) == 0;
    }

public:
    MopFile(const std::string& filename = "") {
        keywords.clear();
        title = "";
        comment = "";
        atoms.clear();
        isCartesian = false;
        if (!filename.empty()) read(filename);
    }

    void read(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) throw std::runtime_error("Cannot open file");
        std::vector<std::string> lines;
        std::string line;
        while (std::getline(file, line)) {
            if (!line.empty()) {
                std::stringstream ss(line);
                std::string trimmed;
                ss >> std::ws;
                std::getline(ss, trimmed);
                if (!trimmed.empty()) lines.push_back(trimmed);
            }
        }
        file.close();
        if (lines.empty()) throw std::runtime_error("Empty file");
        std::stringstream ss0(lines[0]);
        std::string kw;
        while (ss0 >> kw) keywords.push_back(kw);
        title = lines.size() > 1 ? lines[1] : "";
        comment = lines.size() > 2 ? lines[2] : "";
        isCartesian = false;
        for (const auto& k : keywords) {
            if (startsWith(std::string(1, std::toupper(k[0])) + k.substr(1), "XYZ")) {
                isCartesian = true;
                break;
            }
        }
        atoms.clear();
        for (size_t i = 3; i < lines.size(); ++i) {
            std::stringstream ss(lines[i]);
            std::string symbol;
            ss >> symbol;
            if (symbol.empty()) continue;
            std::map<std::string, double> atom;
            atom["symbol_str"] = 0; // Placeholder for string
            // Store symbol as string somehow; for simplicity, print separately
            double v1, o1, v2, o2, v3, o3, c1, c2, c3;
            if (isCartesian) {
                ss >> v1 >> o1 >> v2 >> o2 >> v3 >> o3;
                atom["x"] = v1; atom["opt_x"] = o1;
                atom["y"] = v2; atom["opt_y"] = o2;
                atom["z"] = v3; atom["opt_z"] = o3;
            } else {
                ss >> v1 >> o1 >> v2 >> o2 >> v3 >> o3 >> c1 >> c2;
                atom["dist"] = v1; atom["opt_d"] = o1;
                atom["angle"] = v2; atom["opt_a"] = o2;
                atom["dihed"] = v3; atom["opt_di"] = o3;
                atom["conn1"] = c1; atom["conn2"] = c2;
                ss >> c3;
                atom["conn3"] = ss.fail() ? 0 : c3;
            }
            atoms.push_back(atom);
        }
    }

    void write(const std::string& filename) {
        std::ofstream file(filename);
        if (!file.is_open()) throw std::runtime_error("Cannot write file");
        for (const auto& kw : keywords) file << kw << " ";
        file << "\n" << title << "\n" << comment << "\n";
        for (const auto& atom : atoms) {
            // Symbol not stored; assume we need to add it separately or modify class
            // For this impl, skip symbol print or assume it's stored elsewhere
            // To fix, use struct instead of map for atoms
            if (isCartesian) {
                file << std::fixed << std::setprecision(8) << atom.at("x") << " " << (int)atom.at("opt_x") << " "
                     << std::setprecision(8) << atom.at("y") << " " << (int)atom.at("opt_y") << " "
                     << std::setprecision(8) << atom.at("z") << " " << (int)atom.at("opt_z") << "\n";
            } else {
                file << std::fixed << std::setprecision(8) << atom.at("dist") << " " << (int)atom.at("opt_d") << " "
                     << std::setprecision(7) << atom.at("angle") << " " << (int)atom.at("opt_a") << " "
                     << std::setprecision(7) << atom.at("dihed") << " " << (int)atom.at("opt_di") << " "
                     << (int)atom.at("conn1") << " " << (int)atom.at("conn2") << " " << (int)atom.at("conn3") << "\n";
            }
        }
        file.close();
    }

    void printProperties() {
        std::cout << "Keywords:";
        for (const auto& kw : keywords) std::cout << " " << kw;
        std::cout << "\nTitle: " << title << "\nComment: " << comment << "\n";
        std::cout << "Geometry Type: " << (isCartesian ? "Cartesian" : "Internal") << "\nAtoms:\n";
        for (const auto& atom : atoms) {
            if (isCartesian) {
                std::cout << "x: " << atom.at("x") << ", opt_x: " << (int)atom.at("opt_x")
                          << ", y: " << atom.at("y") << ", opt_y: " << (int)atom.at("opt_y")
                          << ", z: " << atom.at("z") << ", opt_z: " << (int)atom.at("opt_z") << "\n";
            } else {
                std::cout << "dist: " << atom.at("dist") << ", opt_d: " << (int)atom.at("opt_d")
                          << ", angle: " << atom.at("angle") << ", opt_a: " << (int)atom.at("opt_a")
                          << ", dihed: " << atom.at("dihed") << ", opt_di: " << (int)atom.at("opt_di")
                          << ", conn1: " << (int)atom.at("conn1") << ", conn2: " << (int)atom.at("conn2")
                          << ", conn3: " << (int)atom.at("conn3") << "\n";
            }
        }
    }
};
// ===== end task-411 .MOP =====

// ===== task-412 .MOV [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint8_t *data;
    size_t length;
    size_t pos;
    // Use arrays or structs for properties (simplified with printf instead of storing all)
} MovParser;

uint32_t read_uint32(MovParser *parser) {
    uint32_t val = (parser->data[parser->pos] << 24) | (parser->data[parser->pos+1] << 16) |
                   (parser->data[parser->pos+2] << 8) | parser->data[parser->pos+3];
    parser->pos += 4;
    return val;
}

uint16_t read_uint16(MovParser *parser) {
    uint16_t val = (parser->data[parser->pos] << 8) | parser->data[parser->pos+1];
    parser->pos += 2;
    return val;
}

double read_fixed1616(MovParser *parser) {
    return (double)read_uint32(parser) / 65536.0;
}

double read_fixed88(MovParser *parser) {
    return (double)read_uint16(parser) / 256.0;
}

char* read_string(MovParser *parser, int length) {
    char* str = malloc(length + 1);
    memcpy(str, &parser->data[parser->pos], length);
    str[length] = '\0';
    parser->pos += length;
    return str;
}

void parse_atom(MovParser *parser) {
    size_t start_pos = parser->pos;
    uint32_t size = read_uint32(parser);
    char* type = read_string(parser, 4);
    if (strcmp(type, "ftyp") == 0) {
        char* major = read_string(parser, 4);
        uint32_t minor = read_uint32(parser);
        printf("Major Brand: %s\n", major);
        printf("Minor Version: %u\n", minor);
        printf("Compatible Brands: ");
        while (parser->pos < start_pos + size) {
            char* brand = read_string(parser, 4);
            printf("%s ", brand);
            free(brand);
        }
        printf("\n");
        free(major);
    } else if (strcmp(type, "mvhd") == 0) {
        parser->pos += 1; // version
        parser->pos += 3; // flags
        printf("Movie Creation Time: %u\n", read_uint32(parser));
        printf("Movie Modification Time: %u\n", read_uint32(parser));
        printf("Time Scale: %u\n", read_uint32(parser));
        printf("Movie Duration: %u\n", read_uint32(parser));
        printf("Preferred Rate: %f\n", read_fixed1616(parser));
        printf("Preferred Volume: %f\n", read_fixed88(parser));
        parser->pos += 10; // reserved
        parser->pos += 36; // matrix
        printf("Preview Time: %u\n", read_uint32(parser));
        printf("Preview Duration: %u\n", read_uint32(parser));
        printf("Poster Time: %u\n", read_uint32(parser));
        printf("Selection Time: %u\n", read_uint32(parser));
        printf("Selection Duration: %u\n", read_uint32(parser));
        printf("Current Time: %u\n", read_uint32(parser));
        printf("Next Track ID: %u\n", read_uint32(parser));
    } else if (strcmp(type, "tkhd") == 0) {
        parser->pos += 1; // version
        parser->pos += 3; // flags
        printf("Track Creation Time: %u\n", read_uint32(parser));
        printf("Track Modification Time: %u\n", read_uint32(parser));
        printf("Track ID: %u\n", read_uint32(parser));
        parser->pos += 4; // reserved
        printf("Track Duration: %u\n", read_uint32(parser));
        parser->pos += 8; // reserved
        int16_t layer = (int16_t)read_uint16(parser);
        printf("Track Layer: %d\n", layer);
        int16_t alt_group = (int16_t)read_uint16(parser);
        printf("Alternate Group: %d\n", alt_group);
        printf("Track Volume: %f\n", read_fixed88(parser));
        parser->pos += 2; // reserved
        parser->pos += 36; // matrix
        printf("Track Width: %f\n", read_fixed1616(parser));
        printf("Track Height: %f\n", read_fixed1616(parser));
    } else if (strcmp(type, "hdlr") == 0) {
        parser->pos += 8; // version, flags, component type
        char* htype = read_string(parser, 4);
        printf("Handler Type: %s\n", htype);
        free(htype);
    }
    free(type);
    parser->pos = start_pos + size;
}

void parse(MovParser *parser) {
    while (parser->pos < parser->length) {
        parse_atom(parser);
    }
}

MovParser* mov_parser_init(const char* filename) {
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    size_t len = ftell(f);
    fseek(f, 0, SEEK_SET);
    MovParser* parser = malloc(sizeof(MovParser));
    parser->data = malloc(len);
    fread(parser->data, 1, len, f);
    fclose(f);
    parser->length = len;
    parser->pos = 0;
    return parser;
}

void print_properties(MovParser *parser) {
    parser->pos = 0;  // Reset to print again
    parse(parser);
}

void write_file(MovParser *parser, const char* output_filename) {
    FILE *f = fopen(output_filename, "wb");
    if (f) {
        fwrite(parser->data, 1, parser->length, f);
        fclose(f);
        printf("File written to %s\n", output_filename);
    }
}

void mov_parser_free(MovParser *parser) {
    free(parser->data);
    free(parser);
}

