// ===== task-461 .NSF [C++] =====
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <iomanip>
#include <cstring>

class NSFHandler {
private:
    std::string filename;
    std::vector<unsigned char> header;
    std::vector<unsigned char> payload;
    std::string signature;
    unsigned char version;
    unsigned char total_songs;
    unsigned char starting_song;
    unsigned short load_address;
    unsigned short init_address;
    unsigned short play_address;
    std::string song_name;
    std::string artist;
    std::string copyright_info;
    unsigned short ntsc_speed;
    unsigned char bankswitch_init[8];
    unsigned short pal_speed;
    unsigned char video_system;
    unsigned char extra_chips;
    unsigned char reserved[4];

public:
    NSFHandler(const std::string& fn) : filename(fn) {
        read();
    }

    void read() {
        std::ifstream file(filename, std::ios::binary | std::ios::ate);
        if (!file) {
            throw std::runtime_error("Cannot open file");
        }
        size_t size = file.tellg();
        file.seekg(0);
        if (size < 128) {
            throw std::runtime_error("Invalid NSF file: too short");
        }
        std::vector<unsigned char> data(size);
        file.read(reinterpret_cast<char*>(data.data()), size);

        header.assign(data.begin(), data.begin() + 128);
        payload.assign(data.begin() + 128, data.end());

        // Signature
        signature.assign(header.begin(), header.begin() + 5);

        // Version
        version = header[5];

        // Total Songs
        total_songs = header[6];

        // Starting Song
        starting_song = header[7];

        // Load Address
        load_address = (header[9] << 8) | header[8];

        // Init Address
        init_address = (header[11] << 8) | header[10];

        // Play Address
        play_address = (header[13] << 8) | header[12];

        // Song Name
        song_name = get_null_term_string(&header[14], 32);

        // Artist
        artist = get_null_term_string(&header[46], 32);

        // Copyright
        copyright_info = get_null_term_string(&header[78], 32);

        // NTSC Speed
        ntsc_speed = (header[111] << 8) | header[110];

        // Bankswitch Init
        std::memcpy(bankswitch_init, &header[112], 8);

        // PAL Speed
        pal_speed = (header[121] << 8) | header[120];

        // Video System
        video_system = header[122];

        // Extra Chips
        extra_chips = header[123];

        // Reserved
        std::memcpy(reserved, &header[124], 4);
    }

    std::string get_null_term_string(const unsigned char* ptr, size_t max_len) {
        std::string str;
        for (size_t i = 0; i < max_len; ++i) {
            if (ptr[i] == 0) break;
            str += static_cast<char>(ptr[i]);
        }
        return str.empty() ? "<?>" : str;
    }

    void print_properties() {
        std::cout << "NSF Properties:" << std::endl;
        std::cout << "Signature: " << signature << std::endl;
        std::cout << "Version: " << static_cast<int>(version) << std::endl;
        std::cout << "Total Songs: " << static_cast<int>(total_songs) << std::endl;
        std::cout << "Starting Song: " << static_cast<int>(starting_song) << std::endl;
        std::cout << "Load Address: 0x" << std::hex << std::uppercase << std::setw(4) << std::setfill('0') << load_address << std::endl;
        std::cout << "Init Address: 0x" << std::hex << std::uppercase << std::setw(4) << std::setfill('0') << init_address << std::endl;
        std::cout << "Play Address: 0x" << std::hex << std::uppercase << std::setw(4) << std::setfill('0') << play_address << std::endl;
        std::cout << "Song Name: " << song_name << std::endl;
        std::cout << "Artist: " << artist << std::endl;
        std::cout << "Copyright: " << copyright_info << std::endl;
        std::cout << "NTSC Speed: " << ntsc_speed << std::endl;
        std::cout << "Bankswitch Init: [";
        for (int i = 0; i < 8; ++i) {
            std::cout << "0x" << std::hex << std::uppercase << std::setw(2) << std::setfill('0') << static_cast<int>(bankswitch_init[i]);
            if (i < 7) std::cout << ", ";
        }
        std::cout << "]" << std::endl;
        std::cout << "PAL Speed: " << pal_speed << std::endl;
        std::cout << "Video System: 0x" << std::hex << std::uppercase << std::setw(2) << std::setfill('0') << static_cast<int>(video_system) << std::endl;
        std::cout << "Extra Sound Chips: 0x" << std::hex << std::uppercase << std::setw(2) << std::setfill('0') << static_cast<int>(extra_chips) << std::endl;
        std::cout << "Reserved: [";
        for (int i = 0; i < 4; ++i) {
            std::cout << "0x" << std::hex << std::uppercase << std::setw(2) << std::setfill('0') << static_cast<int>(reserved[i]);
            if (i < 3) std::cout << ", ";
        }
        std::cout << "]" << std::endl;
        std::cout << "Data Payload Size: " << payload.size() << " bytes" << std::endl;
    }

    void write(const std::string& output_filename) {
        // Rebuild header
        header[5] = version;
        header[6] = total_songs;
        header[7] = starting_song;
        header[8] = load_address & 0xFF;
        header[9] = (load_address >> 8) & 0xFF;
        header[10] = init_address & 0xFF;
        header[11] = (init_address >> 8) & 0xFF;
        header[12] = play_address & 0xFF;
        header[13] = (play_address >> 8) & 0xFF;
        set_null_term_string(&header[14], song_name, 32);
        set_null_term_string(&header[46], artist, 32);
        set_null_term_string(&header[78], copyright_info, 32);
        header[110] = ntsc_speed & 0xFF;
        header[111] = (ntsc_speed >> 8) & 0xFF;
        std::memcpy(&header[112], bankswitch_init, 8);
        header[120] = pal_speed & 0xFF;
        header[121] = (pal_speed >> 8) & 0xFF;
        header[122] = video_system;
        header[123] = extra_chips;
        std::memcpy(&header[124], reserved, 4);

        std::ofstream out(output_filename, std::ios::binary);
        if (!out) {
            throw std::runtime_error("Cannot write file");
        }
        out.write(reinterpret_cast<const char*>(header.data()), 128);
        out.write(reinterpret_cast<const char*>(payload.data()), payload.size());
    }

    void set_null_term_string(unsigned char* ptr, const std::string& str, size_t max_len) {
        size_t len = std::min(str.length(), max_len - 1);
        std::memcpy(ptr, str.c_str(), len);
        ptr[len] = 0;
        std::memset(ptr + len + 1, 0, max_len - len - 1);
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <input.nsf> [output.nsf]" << std::endl;
        return 1;
    }
    try {
        NSFHandler handler(argv[1]);
        handler.print_properties();
        if (argc > 2) {
            handler.write(argv[2]);
            std::cout << "Written to " << argv[2] << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
// ===== end task-461 .NSF =====

// ===== task-462 .NSV [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    char* filename;
    uint8_t* data;
    size_t size;
    struct {
        uint32_t header_length;
        uint32_t file_length;
        uint32_t metadata_length;
        uint32_t toc_entries;
        uint32_t toc_size;
        char* metadata;
        uint32_t* toc;
    } header;
    struct {
        char video_codec[5];
        char audio_codec[5];
        uint16_t width;
        uint16_t height;
        uint8_t framerate;
        int16_t sync_offset;
    } bitstream_props;
} NSVFile;

NSVFile* nsv_create(const char* filename) {
    NSVFile* nsv = malloc(sizeof(NSVFile));
    nsv->filename = strdup(filename);
    nsv->data = NULL;
    nsv->size = 0;
    memset(&nsv->header, 0, sizeof(nsv->header));
    memset(&nsv->bitstream_props, 0, sizeof(nsv->bitstream_props));
    return nsv;
}

void nsv_read(NSVFile* nsv) {
    FILE* f = fopen(nsv->filename, "rb");
    if (!f) return;
    fseek(f, 0, SEEK_END);
    nsv->size = ftell(f);
    fseek(f, 0, SEEK_SET);
    nsv->data = malloc(nsv->size);
    fread(nsv->data, 1, nsv->size, f);
    fclose(f);
    nsv_decode(nsv);
}

void nsv_decode(NSVFile* nsv) {
    size_t offset = 0;
    char sig[5] = {0};
    memcpy(sig, nsv->data + offset, 4); offset += 4;
    if (strcmp(sig, "NSVf") == 0) {
        memcpy(&nsv->header.header_length, nsv->data + offset, 4); offset += 4;
        memcpy(&nsv->header.file_length, nsv->data + offset, 4); offset += 4;
        memcpy(&nsv->header.metadata_length, nsv->data + offset, 4); offset += 4;
        memcpy(&nsv->header.toc_entries, nsv->data + offset, 4); offset += 4;
        memcpy(&nsv->header.toc_size, nsv->data + offset, 4); offset += 4;
        nsv->header.metadata = malloc(nsv->header.metadata_length + 1);
        memcpy(nsv->header.metadata, nsv->data + offset, nsv->header.metadata_length);
        nsv->header.metadata[nsv->header.metadata_length] = '\0';
        offset += nsv->header.metadata_length;
        nsv->header.toc = malloc(nsv->header.toc_entries * sizeof(uint32_t));
        for (uint32_t i = 0; i < nsv->header.toc_entries; i++) {
            memcpy(&nsv->header.toc[i], nsv->data + offset, 4);
            offset += 4;
        }
    }
    // Find first sync frame
    while (offset < nsv->size - 4) {
        char sync_sig[5] = {0};
        memcpy(sync_sig, nsv->data + offset, 4);
        if (strcmp(sync_sig, "NSVs") == 0) {
            offset += 4;
            memcpy(nsv->bitstream_props.video_codec, nsv->data + offset, 4); nsv->bitstream_props.video_codec[4] = '\0'; offset += 4;
            memcpy(nsv->bitstream_props.audio_codec, nsv->data + offset, 4); nsv->bitstream_props.audio_codec[4] = '\0'; offset += 4;
            memcpy(&nsv->bitstream_props.width, nsv->data + offset, 2); offset += 2;
            memcpy(&nsv->bitstream_props.height, nsv->data + offset, 2); offset += 2;
            nsv->bitstream_props.framerate = nsv->data[offset]; offset += 1;
            memcpy(&nsv->bitstream_props.sync_offset, nsv->data + offset, 2); offset += 2;
            break;
        }
        offset++;
    }
}

void nsv_print_properties(NSVFile* nsv) {
    printf("NSV File Properties:\n");
    printf("- Header Length: %u\n", nsv->header.header_length);
    printf("- File Length: %u\n", nsv->header.file_length);
    printf("- Metadata Length: %u\n", nsv->header.metadata_length);
    printf("- TOC Entries: %u\n", nsv->header.toc_entries);
    printf("- TOC Size: %u\n", nsv->header.toc_size);
    printf("- Metadata: %s\n", nsv->header.metadata ? nsv->header.metadata : "None");
    printf("- TOC: [");
    for (uint32_t i = 0; i < nsv->header.toc_entries; i++) {
        printf("%u%s", nsv->header.toc[i], i < nsv->header.toc_entries - 1 ? ", " : "");
    }
    printf("]\n");
    printf("- Bitstream Video Codec: %s\n", nsv->bitstream_props.video_codec);
    printf("- Bitstream Audio Codec: %s\n", nsv->bitstream_props.audio_codec);
    printf("- Bitstream Width: %u\n", nsv->bitstream_props.width);
    printf("- Bitstream Height: %u\n", nsv->bitstream_props.height);
    printf("- Bitstream Framerate: %u\n", nsv->bitstream_props.framerate);
    printf("- Bitstream Sync Offset: %d\n", nsv->bitstream_props.sync_offset);
}

void nsv_write(NSVFile* nsv, const char* new_filename) {
    FILE* f = fopen(new_filename, "wb");
    if (f) {
        fwrite(nsv->data, 1, nsv->size, f);
        fclose(f);
    }
}

void nsv_destroy(NSVFile* nsv) {
    free(nsv->data);
    free(nsv->header.metadata);
    free(nsv->header.toc);
    free(nsv->filename);
    free(nsv);
}

