// ===== task-571 .PROTO [C++] =====
#include <fstream>
#include <vector>
#include <string>
#include <iostream>
#include <iomanip>
#include <cstdint>
#include <stdexcept>

struct Field {
    uint32_t field_number;
    uint32_t wire_type;
    std::vector<uint8_t> value; // For varint, encode to bytes; for message, serialize sub-fields
    std::vector<Field> sub_fields; // If message
};

class ProtoParser {
private:
    std::vector<uint8_t> data;
    std::vector<Field> parsed;

    uint64_t read_varint(size_t& pos) {
        uint64_t result = 0;
        int shift = 0;
        while (true) {
            uint8_t b = data[pos++];
            result |= static_cast<uint64_t>(b & 0x7F) << shift;
            if (!(b & 0x80)) break;
            shift += 7;
            if (shift > 63) throw std::runtime_error("Varint too long");
        }
        return result;
    }

    std::vector<Field> parse_message(size_t start, size_t end) {
        std::vector<Field> fields;
        size_t pos = start;
        while (pos < end) {
            uint64_t key = read_varint(pos);
            uint32_t field_number = key >> 3;
            uint32_t wire_type = key & 0x7;
            Field f;
            f.field_number = field_number;
            f.wire_type = wire_type;
            if (wire_type == 0) {
                uint64_t val = read_varint(pos);
                f.value = encode_varint(val); // Store as bytes for consistency
            } else if (wire_type == 5) {
                f.value.assign(data.begin() + pos, data.begin() + pos + 4);
                pos += 4;
            } else if (wire_type == 1) {
                f.value.assign(data.begin() + pos, data.begin() + pos + 8);
                pos += 8;
            } else if (wire_type == 2) {
                uint64_t length = read_varint(pos);
                size_t sub_start = pos;
                size_t sub_end = pos + length;
                try {
                    auto sub_parsed = parse_message(sub_start, sub_end);
                    if (pos == sub_end) {
                        f.sub_fields = sub_parsed;
                    } else {
                        f.value.assign(data.begin() + sub_start, data.begin() + sub_end);
                    }
                } catch (...) {
                    f.value.assign(data.begin() + sub_start, data.begin() + sub_end);
                }
                pos = sub_end;
            } else {
                throw std::runtime_error("Unknown wire type");
            }
            fields.push_back(f);
        }
        return fields;
    }

    void print_properties(const std::vector<Field>& fields, const std::string& indent) {
        for (const auto& field : fields) {
            std::cout << indent << "Field " << field.field_number << " (wire type " << field.wire_type << "): ";
            if (field.wire_type == 0) {
                size_t p = 0;
                uint64_t val = read_varint_from_bytes(field.value, p);
                std::cout << "varint " << val << std::endl;
            } else if (field.wire_type == 1 || field.wire_type == 5) {
                std::cout << "fixed [";
                for (size_t i = 0; i < field.value.size(); ++i) {
                    std::cout << std::hex << std::setfill('0') << std::setw(2) << static_cast<int>(field.value[i]) << (i < field.value.size() - 1 ? " " : "");
                }
                std::cout << "]" << std::dec << std::endl;
            } else if (field.wire_type == 2) {
                if (!field.sub_fields.empty()) {
                    std::cout << "message {" << std::endl;
                    print_properties(field.sub_fields, indent + "  ");
                    std::cout << indent << "}" << std::endl;
                } else {
                    std::cout << "bytes [";
                    for (size_t i = 0; i < field.value.size(); ++i) {
                        std::cout << std::hex << std::setfill('0') << std::setw(2) << static_cast<int>(field.value[i]) << (i < field.value.size() - 1 ? " " : "");
                    }
                    std::cout << "]" << std::dec << std::endl;
                }
            }
        }
    }

    std::vector<uint8_t> encode_varint(uint64_t value) {
        std::vector<uint8_t> bytes;
        while (true) {
            uint8_t byte_val = value & 0x7F;
            value >>= 7;
            if (value) byte_val |= 0x80;
            bytes.push_back(byte_val);
            if (!value) break;
        }
        return bytes;
    }

    uint64_t read_varint_from_bytes(const std::vector<uint8_t>& bytes, size_t& pos) {
        uint64_t result = 0;
        int shift = 0;
        while (true) {
            uint8_t b = bytes[pos++];
            result |= static_cast<uint64_t>(b & 0x7F) << shift;
            if (!(b & 0x80)) break;
            shift += 7;
        }
        return result;
    }

    std::vector<uint8_t> encode_message(const std::vector<Field>& fields) {
        std::vector<uint8_t> result;
        for (const auto& field : fields) {
            uint64_t key = (static_cast<uint64_t>(field.field_number) << 3) | field.wire_type;
            auto key_bytes = encode_varint(key);
            result.insert(result.end(), key_bytes.begin(), key_bytes.end());
            if (field.wire_type == 0) {
                result.insert(result.end(), field.value.begin(), field.value.end());
            } else if (field.wire_type == 1 || field.wire_type == 5) {
                result.insert(result.end(), field.value.begin(), field.value.end());
            } else if (field.wire_type == 2) {
                std::vector<uint8_t> sub_data;
                if (!field.sub_fields.empty()) {
                    sub_data = encode_message(field.sub_fields);
                } else {
                    sub_data = field.value;
                }
                auto len_bytes = encode_varint(sub_data.size());
                result.insert(result.end(), len_bytes.begin(), len_bytes.end());
                result.insert(result.end(), sub_data.begin(), sub_data.end());
            }
        }
        return result;
    }

public:
    ProtoParser(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file) throw std::runtime_error("Cannot open file");
        data = std::vector<uint8_t>((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
        parsed = parse_message(0, data.size());
    }

    void print_properties() {
        print_properties(parsed, "");
    }

    void write(const std::string& filename) {
        auto encoded = encode_message(parsed);
        std::ofstream file(filename, std::ios::binary);
        file.write(reinterpret_cast<const char*>(encoded.data()), encoded.size());
    }
};
// ===== end task-571 .PROTO =====

// ===== task-572 .PRP [C++] =====
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <sstream>
using namespace std;

struct Node {
    string type;
    string name;
    string defaultValue;
    vector<string> values;
    vector<Node> children;
};

class PRPFile {
private:
    string filepath;
    vector<Node> structure;

    void parse(const string& text) {
        istringstream iss(text);
        string line;
        vector<Node*> stack;
        Node* current = new Node{"root", "", "", {}, {}};
        structure = current->children;
        while (getline(iss, line)) {
            line = line.substr(0, line.find("//")); // Ignore comments
            istringstream lineIss(line);
            string token;
            vector<string> parts;
            while (lineIss >> token) parts.push_back(token);
            if (parts.empty()) continue;
            if (parts[0] == "end") {
                if (!stack.empty()) {
                    current = stack.back();
                    stack.pop_back();
                }
                continue;
            }
            if (parts[0] == "Subject") {
                Node node = {"Subject", parts[1], "", {}, {}};
                current->children.push_back(node);
                stack.push_back(current);
                current = &current->children.back();
            } else if (parts[0] == "Metaclass") {
                Node node = {"Metaclass", parts[1], "", {}, {}};
                current->children.push_back(node);
                stack.push_back(current);
                current = &current->children.back();
            } else if (parts[0] == "Property") {
                Node node = {"Property", parts[1], "", {}, {}};
                current->children.push_back(node);
                stack.push_back(current);
                current = &current->children.back();
            } else if (parts[0] == "Enum") {
                string vals = parts[1].substr(1, parts[1].length() - 2);
                istringstream valIss(vals);
                string val;
                vector<string> values;
                while (getline(valIss, val, ',')) values.push_back(val);
                string def = parts.size() > 2 ? parts[2].substr(1, parts[2].length() - 2) : "";
                Node node = {"Enum", "", def, values, {}};
                current->children.push_back(node);
            }
        }
    }

    void printProperties(const vector<Node>& nodes, int indent = 0) {
        for (const auto& prop : nodes) {
            for (int i = 0; i < indent; ++i) cout << "  ";
            cout << prop.type << ": " << prop.name << endl;
            if (!prop.values.empty()) {
                for (int i = 0; i < indent + 1; ++i) cout << "  ";
                cout << "Values: ";
                for (size_t j = 0; j < prop.values.size(); ++j) {
                    cout << prop.values[j];
                    if (j < prop.values.size() - 1) cout << ", ";
                }
                cout << endl;
            }
            if (!prop.defaultValue.empty()) {
                for (int i = 0; i < indent + 1; ++i) cout << "  ";
                cout << "Default: " << prop.defaultValue << endl;
            }
            printProperties(prop.children, indent + 1);
        }
    }

    string serialize(const vector<Node>& nodes, int indent = 0) {
        stringstream ss;
        for (const auto& prop : nodes) {
            for (int i = 0; i < indent; ++i) ss << "  ";
            if (prop.type == "Subject") ss << "Subject " << prop.name << endl;
            else if (prop.type == "Metaclass") ss << "Metaclass " << prop.name << endl;
            else if (prop.type == "Property") ss << "Property " << prop.name << endl;
            ss << serialize(prop.children, indent + 1);
            if (prop.type != "Enum") {
                for (int i = 0; i < indent; ++i) ss << "  ";
                ss << "end" << endl;
            } else {
                for (int i = 0; i < indent; ++i) ss << "  ";
                ss << "Enum \"";
                for (size_t j = 0; j < prop.values.size(); ++j) {
                    ss << prop.values[j];
                    if (j < prop.values.size() - 1) ss << ",";
                }
                ss << "\", \"" << prop.defaultValue << "\"\n";
            }
        }
        return ss.str();
    }

public:
    void open(const string& fp) {
        filepath = fp;
        ifstream file(fp);
        stringstream buffer;
        buffer << file.rdbuf();
        parse(buffer.str());
    }

    void print_properties() {
        printProperties(structure);
    }

    void write(const string& fp) {
        ofstream file(fp);
        file << serialize(structure);
    }
};

