// ===== task-581 .PTS [C] =====
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double x, y, z;
    int intensity, r, g, b;
} Point;

typedef struct {
    int num_points;
    Point *points;
} PTSFile;

PTSFile* pts_create(const char *filename) {
    PTSFile *pts = malloc(sizeof(PTSFile));
    pts->num_points = 0;
    pts->points = NULL;
    if (filename) {
        pts_read(pts, filename);
    }
    return pts;
}

void pts_read(PTSFile *pts, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Failed to open file");
        exit(1);
    }

    char line[256];
    if (fgets(line, sizeof(line), fp)) {
        pts->num_points = atoi(line);
    }

    if (pts->points) free(pts->points);
    pts->points = malloc(pts->num_points * sizeof(Point));
    int idx = 0;
    while (fgets(line, sizeof(line), fp) && idx < pts->num_points) {
        char *token = strtok(line, " ");
        if (token) pts->points[idx].x = atof(token);
        token = strtok(NULL, " ");
        if (token) pts->points[idx].y = atof(token);
        token = strtok(NULL, " ");
        if (token) pts->points[idx].z = atof(token);
        token = strtok(NULL, " ");
        if (token) pts->points[idx].intensity = atoi(token);
        token = strtok(NULL, " ");
        if (token) pts->points[idx].r = atoi(token);
        token = strtok(NULL, " ");
        if (token) pts->points[idx].g = atoi(token);
        token = strtok(NULL, " ");
        if (token) pts->points[idx].b = atoi(token);
        idx++;
    }
    fclose(fp);

    if (idx != pts->num_points) {
        fprintf(stderr, "Point count mismatch\n");
        exit(1);
    }
}

void pts_print_properties(const PTSFile *pts) {
    printf("Number of points: %d\n", pts->num_points);
    for (int i = 0; i < pts->num_points; i++) {
        const Point *p = &pts->points[i];
        printf("Point %d: x=%.6f, y=%.6f, z=%.6f, intensity=%d, r=%d, g=%d, b=%d\n",
               i + 1, p->x, p->y, p->z, p->intensity, p->r, p->g, p->b);
    }
}

void pts_write(const PTSFile *pts, const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("Failed to open file for writing");
        exit(1);
    }
    fprintf(fp, "%d\n", pts->num_points);
    for (int i = 0; i < pts->num_points; i++) {
        const Point *p = &pts->points[i];
        fprintf(fp, "%.6f %.6f %.6f %d %d %d %d\n",
                p->x, p->y, p->z, p->intensity, p->r, p->g, p->b);
    }
    fclose(fp);
}

void pts_destroy(PTSFile *pts) {
    free(pts->points);
    free(pts);
}
// ===== end task-581 .PTS =====

// ===== task-582 .PTX [C++] =====
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <regex>

class PTXParser {
private:
    std::string version;
    std::string target;
    std::string address_size;
    std::vector<std::string> entries;
    std::vector<std::string> funcs;
    std::vector<std::string> variables;
    std::vector<std::string> registers;
    std::string text;

public:
    void open(const std::string& filepath) {
        std::ifstream file(filepath);
        if (!file.is_open()) {
            std::cerr << "Error opening file: " << filepath << std::endl;
            return;
        }
        std::stringstream buffer;
        buffer << file.rdbuf();
        text = buffer.str();
        file.close();
        decode();
    }

    void decode() {
        if (text.empty()) {
            throw std::runtime_error("No file loaded");
        }
        std::istringstream iss(text);
        std::string line;
        while (std::getline(iss, line)) {
            line.erase(0, line.find_first_not_of(" \t"));
            line.erase(line.find_last_not_of(" \t") + 1);
            if (line.empty() || line.substr(0, 2) == "//") continue;
            if (line.substr(0, 8) == ".version") {
                std::regex r("\\.version\\s+(\\S+)");
                std::smatch m;
                if (std::regex_search(line, m, r)) version = m[1];
            } else if (line.substr(0, 7) == ".target") {
                std::regex r("\\.target\\s+(\\S+)");
                std::smatch m;
                if (std::regex_search(line, m, r)) target = m[1];
            } else if (line.substr(0, 13) == ".address_size") {
                std::regex r("\\.address_size\\s+(\\S+)");
                std::smatch m;
                if (std::regex_search(line, m, r)) address_size = m[1];
            } else if (line.substr(0, 6) == ".entry") {
                std::regex r("\\.entry\\s+(\\S+)\\s*\\(?");
                std::smatch m;
                if (std::regex_search(line, m, r)) entries.push_back(m[1]);
            } else if (line.substr(0, 5) == ".func") {
                std::regex r("\\.func\\s+(\\S+)\\s*\\(?");
                std::smatch m;
                if (std::regex_search(line, m, r)) funcs.push_back(m[1]);
            } else if (line.substr(0, 7) == ".global" || line.substr(0, 6) == ".const" || line.substr(0, 7) == ".shared") {
                variables.push_back(line);
            } else if (line.substr(0, 4) == ".reg") {
                registers.push_back(line);
            }
        }
    }

    void print_properties() const {
        std::cout << "Version: " << (version.empty() ? "Not found" : version) << std::endl;
        std::cout << "Target: " << (target.empty() ? "Not found" : target) << std::endl;
        std::cout << "Address Size: " << (address_size.empty() ? "64 (default)" : address_size) << std::endl;
        std::cout << "Entry Points: ";
        if (entries.empty()) {
            std::cout << "None";
        } else {
            for (size_t i = 0; i < entries.size(); ++i) {
                std::cout << entries[i] << (i < entries.size() - 1 ? ", " : "");
            }
        }
        std::cout << std::endl;
        std::cout << "Functions: ";
        if (funcs.empty()) {
            std::cout << "None";
        } else {
            for (size_t i = 0; i < funcs.size(); ++i) {
                std::cout << funcs[i] << (i < funcs.size() - 1 ? ", " : "");
            }
        }
        std::cout << std::endl;
        std::cout << "Variables:" << std::endl;
        if (variables.empty()) {
            std::cout << "None" << std::endl;
        } else {
            for (const auto& var : variables) {
                std::cout << var << std::endl;
            }
        }
        std::cout << "Registers:" << std::endl;
        if (registers.empty()) {
            std::cout << "None" << std::endl;
        } else {
            for (const auto& reg : registers) {
                std::cout << reg << std::endl;
            }
        }
    }

    void write(const std::string& filepath, const std::string& modified_text = "") const {
        std::string text_to_write = modified_text.empty() ? text : modified_text;
        std::ofstream file(filepath);
        if (!file.is_open()) {
            std::cerr << "Error writing file: " << filepath << std::endl;
            return;
        }
        file << text_to_write;
        file.close();
    }
};

