#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

class S7IFile {
private:
    std::string filename;
    std::string content;

public:
    S7IFile(const std::string& fn) : filename(fn), content("") {}

    void openAndDecode() {
        // Open and read/decode as text (since .S7I is plain text)
        std::ifstream file(filename);
        if (file.is_open()) {
            std::stringstream buffer;
            buffer << file.rdbuf();
            content = buffer.str();
            file.close();
        } else {
            std::cerr << "Error opening file: " << filename << std::endl;
        }
    }

    void printProperties() {
        if (content.empty()) {
            openAndDecode();
        }
        std::cout << "Properties of .S7I file (full decoded content):\n" << std::endl;
        std::cout << content << std::endl;
    }

    void write(const std::string& newContent) {
        std::ofstream file(filename);
        if (file.is_open()) {
            file << newContent;
            file.close();
            std::cout << "Written to " << filename << std::endl;
        } else {
            std::cerr << "Error writing to file: " << filename << std::endl;
        }
    }
};

