// ===== task-752 .UPS [C++] =====
#include <fstream>
#include <vector>
#include <iostream>
#include <iomanip>
#include <zlib.h>  // For CRC32

struct Hunk {
    uint64_t offset;
    std::vector<uint8_t> xorData;  // Including terminating 0
};

class UPSFile {
private:
    std::string magic = "UPS1";
    uint64_t sourceSize = 0;
    uint64_t targetSize = 0;
    std::vector<Hunk> hunks;
    uint32_t sourceCRC = 0;
    uint32_t targetCRC = 0;
    uint32_t patchCRC = 0;

    uint64_t readVLE(std::ifstream& file) {
        uint64_t value = 0;
        int shift = 0;
        while (true) {
            uint8_t byte;
            file.read(reinterpret_cast<char*>(&byte), 1);
            if (byte & 0x80) {
                value += static_cast<uint64_t>(byte & 0x7F) << shift;
                break;
            }
            value += static_cast<uint64_t>(byte | 0x80) << shift;
            shift += 7;
        }
        return value;
    }

    void writeVLE(std::ofstream& file, uint64_t value) {
        while (true) {
            uint8_t byte = static_cast<uint8_t>(value & 0x7F);
            value >>= 7;
            if (value == 0) {
                file.write(reinterpret_cast<char*>(& (uint8_t)(byte | 0x80)), 1);
                break;
            }
            file.write(reinterpret_cast<char*>(&byte), 1);
            value--;
        }
    }

public:
    void openAndDecode(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Cannot open file");
        }
        char magicBuf[5] = {0};
        file.read(magicBuf, 4);
        magic = magicBuf;
        if (magic != "UPS1") {
            throw std::runtime_error("Invalid UPS file");
        }
        sourceSize = readVLE(file);
        targetSize = readVLE(file);
        hunks.clear();
        file.seekg(0, std::ios::end);
        size_t fileSize = file.tellg();
        file.seekg(file.tellg() - (std::streampos)12, std::ios::beg);  // Position before CRCs
        size_t endPos = file.tellg();
        file.seekg(4 + (magic.size() + sizeof(sourceSize) + sizeof(targetSize)), std::ios::beg);  // Approximate, but reset properly
        file.seekg(4, std::ios::beg);  // Reset to after magic
        sourceSize = readVLE(file);
        targetSize = readVLE(file);
        size_t pos = file.tellg();
        while (pos < endPos) {
            uint64_t offset = readVLE(file);
            std::vector<uint8_t> xorData;
            uint8_t byte;
            do {
                file.read(reinterpret_cast<char*>(&byte), 1);
                xorData.push_back(byte);
                pos = file.tellg();
            } while (byte != 0 && pos < endPos);
            hunks.push_back({offset, xorData});
        }
        file.read(reinterpret_cast<char*>(&sourceCRC), 4);
        file.read(reinterpret_cast<char*>(&targetCRC), 4);
        file.read(reinterpret_cast<char*>(&patchCRC), 4);
    }

    void printProperties() const {
        std::cout << "Magic Number: " << magic << std::endl;
        std::cout << "Source File Size: " << sourceSize << std::endl;
        std::cout << "Target File Size: " << targetSize << std::endl;
        std::cout << "Patch Hunks:" << std::endl;
        for (size_t i = 0; i < hunks.size(); ++i) {
            const auto& hunk = hunks[i];
            std::cout << "  Hunk " << i << ":" << std::endl;
            std::cout << "    Relative Offset: " << hunk.offset << std::endl;
            std::cout << "    XOR Data (hex): ";
            for (uint8_t b : hunk.xorData) {
                std::cout << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(b) << " ";
            }
            std::cout << std::dec << std::endl;
        }
        std::cout << "Source CRC32: 0x" << std::hex << std::uppercase << std::setw(8) << std::setfill('0') << sourceCRC << std::endl;
        std::cout << "Target CRC32: 0x" << std::hex << std::uppercase << std::setw(8) << std::setfill('0') << targetCRC << std::endl;
        std::cout << "Patch CRC32: 0x" << std::hex << std::uppercase << std::setw(8) << std::setfill('0') << patchCRC << std::dec << std::endl;
    }

    void write(const std::string& filename) {
        std::ofstream file(filename, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Cannot open file for writing");
        }
        file.write(magic.c_str(), 4);
        writeVLE(file, sourceSize);
        writeVLE(file, targetSize);
        for (const auto& hunk : hunks) {
            writeVLE(file, hunk.offset);
            file.write(reinterpret_cast<const char*>(hunk.xorData.data()), hunk.xorData.size());
        }
        file.write(reinterpret_cast<const char*>(&sourceCRC), 4);
        file.write(reinterpret_cast<const char*>(&targetCRC), 4);
        // Compute patch CRC
        file.seekp(0, std::ios::end);
        size_t sizeWithoutCRC = file.tellp();
        std::vector<uint8_t> tempData(sizeWithoutCRC);
        file.seekp(0, std::ios::beg);
        file.read(reinterpret_cast<char*>(tempData.data()), sizeWithoutCRC);
        patchCRC = crc32(0L, tempData.data(), sizeWithoutCRC);
        file.write(reinterpret_cast<const char*>(&patchCRC), 4);
    }
};
// ===== end task-752 .UPS =====

// ===== task-753 .URL [C++] =====
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <algorithm>

class URLFile {
private:
    std::string filename;
    std::map<std::string, std::string> properties;

public:
    URLFile(const std::string& fn) : filename(fn) {
        std::ifstream file(fn);
        if (!file) {
            std::cerr << "Error opening file." << std::endl;
            return;
        }
        std::string line;
        bool inSection = false;
        while (std::getline(file, line)) {
            line.erase(std::remove_if(line.begin(), line.end(), isspace), line.end());
            if (line == "[InternetShortcut]") {
                inSection = true;
            } else if (inSection && line.find('=') != std::string::npos) {
                size_t pos = line.find('=');
                std::string key = line.substr(0, pos);
                std::string value = line.substr(pos + 1);
                properties[key] = value;
            }
        }
        file.close();
    }

    void printProperties() {
        std::string propsList[7] = {"URL", "WorkingDirectory", "IconIndex", "IconFile", "Modified", "ShowCommand", "HotKey"};
        for (int i = 0; i < 7; ++i) {
            auto it = properties.find(propsList[i]);
            std::string value = (it != properties.end()) ? it->second : "Not present";
            std::cout << propsList[i] << ": " << value << std::endl;
        }
    }

    void setProperty(const std::string& key, const std::string& value) {
        properties[key] = value;
    }

    void write(const std::string& fn = "") {
        std::string outFile = fn.empty() ? filename : fn;
        std::ofstream file(outFile);
        if (!file) {
            std::cerr << "Error writing file." << std::endl;
            return;
        }
        file << "[InternetShortcut]" << std::endl;
        for (const auto& pair : properties) {
            file << pair.first << "=" << pair.second << std::endl;
        }
        file.close();
    }
};
// ===== end task-753 .URL =====

// ===== task-754 .USDZ [C++] =====
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <cstring>

class USDZHandler {
private:
    std::string filepath;
    std::string archiveFormat = "Uncompressed, unencrypted ZIP archive";
    std::string mimeType = "model/vnd.usdz+zip";
    std::string fileExtension = ".usdz";
    std::vector<bool> alignment;
    std::vector<std::string> allowedFileTypes = {".usd", ".usda", ".usdc", ".png", ".jpeg", ".jpg", ".exr", ".avif", ".m4a", ".mp3", ".wav"};
    bool defaultLayer;
    std::string pathConventions = "Forward slashes, UTF-8";
    std::vector<bool> compression;
    std::string encryption = "None";
    std::string metadata = "Optional in default layer";

public:
    USDZHandler(const std::string& filepath) : filepath(filepath) {}

    void readAndPrintProperties() {
        std::ifstream file(filepath, std::ios::binary | std::ios::ate);
        if (!file) {
            std::cerr << "Failed to open file." << std::endl;
            return;
        }
        size_t size = file.tellg();
        file.seekg(0);
        std::vector<char> buffer(size);
        file.read(buffer.data(), size);

        // Basic ZIP parsing
        size_t offset = size - 22;
        while (offset > 0) {
            uint32_t sig;
            memcpy(&sig, &buffer[offset], 4);
            if (sig == 0x06054b50) { // EOCD
                uint16_t numEntries;
                memcpy(&numEntries, &buffer[offset + 10], 2);
                uint32_t cdOffset;
                memcpy(&cdOffset, &buffer[offset + 16], 4);
                std::vector<std::pair<std::string, uint32_t>> entries;
                size_t currentOffset = cdOffset;
                for (uint16_t i = 0; i < numEntries; ++i) {
                    memcpy(&sig, &buffer[currentOffset], 4);
                    if (sig != 0x02014b50) break;
                    uint16_t compMethod;
                    memcpy(&compMethod, &buffer[currentOffset + 10], 2);
                    compression.push_back(compMethod == 0);
                    uint16_t nameLen;
                    memcpy(&nameLen, &buffer[currentOffset + 28], 2);
                    uint16_t extraLen;
                    memcpy(&extraLen, &buffer[currentOffset + 30], 2);
                    uint16_t commentLen;
                    memcpy(&commentLen, &buffer[currentOffset + 32], 2);
                    uint32_t localOffset;
                    memcpy(&localOffset, &buffer[currentOffset + 42], 4);
                    std::string name(&buffer[currentOffset + 46], nameLen);
                    entries.emplace_back(name, localOffset);
                    alignment.push_back(localOffset % 64 == 0);
                    currentOffset += 46 + nameLen + extraLen + commentLen;
                }
                if (!entries.empty()) {
                    size_t dotPos = entries[0].first.find_last_of('.');
                    std::string ext = (dotPos != std::string::npos) ? entries[0].first.substr(dotPos) : "";
                    std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
                    defaultLayer = (ext == ".usd" || ext == ".usda" || ext == ".usdc");
                }
                break;
            }
            --offset;
        }

        std::cout << "Properties:" << std::endl;
        std::cout << "Archive Format: " << archiveFormat << std::endl;
        std::cout << "MIME Type: " << mimeType << std::endl;
        std::cout << "File Extension: " << fileExtension << std::endl;
        std::cout << "Alignment: ";
        for (bool a : alignment) std::cout << a << " ";
        std::cout << std::endl;
        std::cout << "Allowed File Types: ";
        for (const auto& t : allowedFileTypes) std::cout << t << " ";
        std::cout << std::endl;
        std::cout << "Default Layer: " << defaultLayer << std::endl;
        std::cout << "Path Conventions: " << pathConventions << std::endl;
        std::cout << "Compression: ";
        for (bool c : compression) std::cout << c << " ";
        std::cout << std::endl;
        std::cout << "Encryption: " << encryption << std::endl;
        std::cout << "Metadata: " << metadata << std::endl;
    }

    void writeSampleUsdz(const std::string& outputPath) {
        std::ofstream out(outputPath, std::ios::binary);
        if (!out) {
            std::cerr << "Failed to create file." << std::endl;
            return;
        }
        // Simple ZIP structure for sample
        // Local header for sample.usda
        const char localHeader[] = {0x50, 0x4b, 0x03, 0x04, 0x0a, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0b, 0x00, 0x00, 0x00, 0x0b, 0x00, 0x00, 0x00};  // Placeholder
        out.write(localHeader, sizeof(localHeader));
        out.write("sample.usda", 11);
        std::string content = "#usda 1.0\n";
        out.write(content.c_str(), content.size());
        // Add more entries as needed
        // Central directory and EOCD would be added similarly
        std::cout << "Wrote sample USDZ to " << outputPath << std::endl;
    }
};

