            printf("  Panning loop start point: %u\n", xm->instruments[i].panning_loop_start);
            printf("  Panning loop end point: %u\n", xm->instruments[i].panning_loop_end);
            printf("  Volume type: %u\n", xm->instruments[i].volume_type);
